window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[74]={"id":"074","numero":74,"titre":"Prescription et surveillance des psychotropes","objectifs":[{"id":"74-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et les principales classes de psychotropes","contenu":"<p>Selon la définition de <strong><span class=\"kw-def\">Delay et Deniker</span></strong>, <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">psychotropes</span></strong> sont l'ensemble des substances chimiques d'origine naturelle ou artificielle ayant un <strong>tropisme « psychologique »</strong> — c'est-à-dire susceptibles de <span class=\"kw-clinique\">modifier l'activité mentale</span>, sans préjuger du type de cette modification.</p>\n      <p>On distingue <strong>6 classes</strong> de psychotropes utilisées en psychiatrie :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Antipsychotiques</span></li>\n        <li><span class=\"kw-ttt\">Antidépresseurs</span></li>\n        <li><span class=\"kw-ttt\">Thymorégulateurs</span></li>\n        <li><span class=\"kw-ttt\">Anxiolytiques</span></li>\n        <li><span class=\"kw-ttt\">Hypnotiques</span></li>\n        <li><span class=\"kw-ttt\">Psychostimulants</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> psychotropes sont régis par des <strong>règles de prescription</strong> strictes. Une <span class=\"kw-clinique\">information</span>, voire une <span class=\"kw-clinique\">éducation thérapeutique</span>, est indispensable.</div>\n      <p><span class=\"kw-clinique\">Les</span> approches thérapeutiques reposent sur la modulation des <span class=\"kw-etio\">voies de neurotransmission</span> ou des <span class=\"kw-etio\">canaux ioniques</span>. Le tableau met en correspondance neurotransmetteur, fonction, maladies et classe médicamenteuse :</p>\n      <table >\n        <thead><tr><th>Neurotransmetteur</th><th>Fonctions</th><th>Maladies associées</th><th>Classes médicamenteuses</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dopamine</span></td><td>Plaisir ; émotion ; motricité</td><td><span class=\"kw-etio\">Psychose</span> ; <span class=\"kw-etio\">trouble bipolaire</span></td><td><span class=\"kw-ttt\">Antipsychotiques</span></td></tr>\n          <tr><td><span class=\"kw-def\">Noradrénaline</span></td><td>Vigilance ; attention ; humeur</td><td><span class=\"kw-etio\">Trouble de l'humeur</span> ; <span class=\"kw-etio\">trouble anxieux</span></td><td><span class=\"kw-ttt\">Antidépresseurs</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sérotonine</span></td><td>Humeur ; prise alimentaire ; émotion</td><td><span class=\"kw-etio\">Trouble de l'humeur</span> ; <span class=\"kw-etio\">trouble anxieux</span></td><td><span class=\"kw-ttt\">Antidépresseurs</span> ; <span class=\"kw-ttt\">anxiolytiques</span></td></tr>\n          <tr><td><span class=\"kw-def\">GABA</span> <em>(inhibiteur)</em></td><td>Émotion ; activité neuronale</td><td><span class=\"kw-etio\">Trouble anxieux</span> ; <span class=\"kw-etio\">épilepsie</span></td><td><span class=\"kw-ttt\">Antiépileptiques</span> ; <span class=\"kw-ttt\">anxiolytiques</span></td></tr>\n          <tr><td><span class=\"kw-def\">Glutamate</span> <em>(excitateur)</em></td><td>Motricité ; mémoire ; activité neuronale</td><td><span class=\"kw-etio\">Épilepsie</span></td><td><span class=\"kw-ttt\">Antiépileptiques</span></td></tr>\n          <tr><td><span class=\"kw-def\">Canaux ioniques</span></td><td>Activité neuronale</td><td><span class=\"kw-etio\">Épilepsie</span> ; <span class=\"kw-etio\">trouble anxieux</span></td><td><span class=\"kw-ttt\">Anxiolytiques</span> ; <span class=\"kw-ttt\">antiépileptiques</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Point clé.</strong> Une même classe peut avoir <strong>plusieurs indications</strong>, y compris à la fois pour une maladie neurologique et une maladie mentale. Inversement, une classe utilisée dans une maladie mentale peut induire des effets indésirables neurologiques.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 77 — Addiction aux psychotropes</em></p>","frequence":0},{"id":"74-2","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les principaux chiffres d’utilisation des psychotropes en France, notamment chez les patients âgés (usage et mésusage, pharmaco-épidémiologie)","contenu":"<p>L'utilisation des psychotropes en France est <strong>massive</strong> : environ <strong><span class=\"kw-chiffre\">1 personne sur 4</span></strong> prend un psychotrope au moins <span class=\"kw-chiffre\">1×/an</span>, et <strong><span class=\"kw-chiffre\">1 sur 10</span></strong> en prend régulièrement (<span class=\"kw-chiffre\">≥ 3 mois</span> consécutifs).</p>\n      <p><strong>Sex-ratio</strong> marqué : <span class=\"kw-clinique\">les</span> <strong>femmes</strong> en consomment <span class=\"kw-chiffre\">2× plus</span> que les hommes.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Consommation en France</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Anxiolytiques + hypnotiques</span></td><td>Classe la plus consommée : <span class=\"kw-chiffre\">15-20 %</span> des Français ponctuellement, <span class=\"kw-chiffre\">10 %</span> régulièrement.<br>Après <span class=\"kw-chiffre\">70 ans</span>, <strong><span class=\"kw-chiffre\">1 personne sur 2</span></strong> se voit prescrire de façon <span class=\"kw-alerte\">prolongée</span> un anxiolytique ou un hypnotique.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antidépresseurs</span></td><td>2ᵉ position : <span class=\"kw-chiffre\">10 %</span> ponctuellement, <span class=\"kw-chiffre\">5 %</span> régulièrement. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">ISRS</span> représentent <strong><span class=\"kw-chiffre\">1/3</span></strong> des prescriptions de psychotropes.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antipsychotiques</span></td><td>Environ <span class=\"kw-chiffre\">2 %</span> de la population.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Focus <span class=\"kw-ttt\">benzodiazépines</span></strong> — la France se situait en 2015 au <strong><span class=\"kw-chiffre\">2ᵉ rang européen</span></strong> de consommation :</p>\n      <ul>\n        <li><span class=\"kw-chiffre\">13,4 %</span> de la population a eu <span class=\"kw-chiffre\">≥ 1</span> remboursement de BZD dans l'année.</li>\n        <li>Environ <span class=\"kw-chiffre\">3/4</span> des usagers en prennent sur une durée <span class=\"kw-alerte\">> 6 mois</span> ; plus de <span class=\"kw-chiffre\">20 %</span> consomment 2 molécules de BZD.</li>\n        <li>Prescription initiée par un <strong>médecin généraliste</strong> dans <span class=\"kw-chiffre\">82 %</span> des cas.</li>\n        <li>Profil type du consommateur : <span class=\"kw-chiffre\">65 %</span> de femmes, âge médian <span class=\"kw-chiffre\">57 ans</span>, durée médiane de traitement <span class=\"kw-chiffre\">7 mois</span> (supérieure aux références médicales opposables).</li>\n      </ul>","frequence":0},{"id":"74-3","rang":"A","rubrique":"Définition","titre":"Antipsychotiques : connaître les principales classes et molécules","contenu":"<div class=\"callout callout-info\"><strong>Caractéristique commune.</strong> Sur le plan pharmacologique, <strong>tous <span class=\"kw-clinique\">les</span> antipsychotiques</strong> sont des <strong><span class=\"kw-def\">antagonistes des récepteurs dopaminergiques de type D2</span></strong>.</div>\n      <p>Ils étaient initialement appelés <em>« neuroleptiques »</em> car ceux de 1ʳᵉ génération induisaient d'importantes complications motrices. On distingue deux générations :</p>\n      <table >\n        <thead><tr><th></th><th>Antipsychotiques typiques (1ʳᵉ génération)</th><th>Antipsychotiques atypiques (2ᵉ génération)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Molécules</strong></td><td>\n            <strong>Phénothiazines :</strong> <span class=\"kw-ttt\">cyamémazine</span> ; <span class=\"kw-ttt\">alimémazine</span> ; <span class=\"kw-ttt\">lévomépromazine</span> ; <span class=\"kw-ttt\">chlorpromazine</span><br>\n            <strong>Benzamide :</strong> <span class=\"kw-ttt\">sulpiride</span><br>\n            <strong>Thioxanthène :</strong> <span class=\"kw-ttt\">flupenthixol</span><br>\n            <strong>Butyrophénone :</strong> <span class=\"kw-ttt\">halopéridol</span>\n          </td><td>\n            <span class=\"kw-ttt\">Amisulpride</span> ; <span class=\"kw-ttt\">aripiprazole</span><br>\n            <strong>« -apine » :</strong> <span class=\"kw-ttt\">loxapine</span> ; <span class=\"kw-ttt\">olanzapine</span> ; <span class=\"kw-ttt\">clozapine</span> ; <span class=\"kw-ttt\">quétiapine</span><br>\n            <strong>« -péridone » :</strong> <span class=\"kw-ttt\">rispéridone</span> ; <span class=\"kw-ttt\">palipéridone</span>\n          </td></tr>\n          <tr><td><strong>Effets indésirables</strong></td><td>\n            Effets <span class=\"kw-alerte\">moteurs +++</span><br>\n            Pas de troubles métaboliques\n          </td><td>\n            Effets moteurs possibles mais moindres <em>(sauf <span class=\"kw-ttt\">clozapine</span> : aucun effet moteur)</em><br>\n            <span class=\"kw-alerte\">Troubles métaboliques</span> et prise de poids, surtout avec <span class=\"kw-ttt\">olanzapine</span>, <span class=\"kw-ttt\">clozapine</span> et <span class=\"kw-ttt\">rispéridone</span> (à moindre mesure)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Certains <strong>antiémétiques</strong> comme le <span class=\"kw-ttt\">métoclopramide</span> sont des antipsychotiques « cachés » : ils possèdent des propriétés antagonistes des récepteurs dopaminergiques D2.</div>","frequence":0},{"id":"74-4","rang":"B","rubrique":"Prise en charge","titre":"Antipsychotiques : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients âgés","contenu":"<p><strong>Indications</strong> des antipsychotiques :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Troubles psychotiques</span> :</strong> trouble schizo-affectif, troubles schizophréniques, trouble délirant persistant.</li>\n        <li><strong>Troubles de l'humeur</strong> (certaines molécules seulement), dans le <span class=\"kw-etio\">trouble bipolaire</span> : épisode maniaque — <strong>QORA</strong> (<span class=\"kw-ttt\">quétiapine</span>, <span class=\"kw-ttt\">olanzapine</span>, rispéridone, aripiprazole) ; <span class=\"kw-etio\">épisode dépressif caractérisé</span> — <span class=\"kw-ttt\">quétiapine</span>.</li>\n        <li>Traitement symptomatique de courte durée de l'<span class=\"kw-clinique\">anxiété</span> de l'adulte (<span class=\"kw-ttt\">cyamémazine</span>, <span class=\"kw-ttt\">lévomépromazine</span>), uniquement si <strong>échec</strong> des thérapeutiques habituelles.</li>\n        <li>Symptômes psycho-comportementaux de la <span class=\"kw-etio\">démence</span>.</li>\n        <li>États d'<span class=\"kw-clinique\">agitation psychomotrice</span> (neuroleptiques sédatifs : <span class=\"kw-ttt\">cyamémazine</span>, <span class=\"kw-ttt\">loxapine</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Il n'existe <strong>aucune <span class=\"kw-ci\">contre-indication</span> commune</strong> à tous <span class=\"kw-clinique\">les</span> antipsychotiques. Il s'agit de <strong><span class=\"kw-ci\">CI relatives</span></strong> imposant des <span class=\"kw-ci\">précautions d'emploi</span> selon la molécule.</div>\n      <table >\n        <thead><tr><th>Domaine</th><th><span class=\"kw-ci\">Contre-indications</span> relatives</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td><span class=\"kw-ci\">Hypersensibilité</span> à la molécule ; <span class=\"kw-ci\">ATCD de syndrome malin des neuroleptiques</span> — <span class=\"kw-ci\">contre-indication</span> <strong>à vie</strong> de la molécule incriminée.</td></tr>\n          <tr><td><strong>Rythme / conduction</strong></td><td><span class=\"kw-ci\">Allongement du QT</span> ; <span class=\"kw-clinique\">bradycardie</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">65 bpm</span></span> ; arythmies ; hypokaliémie.</td></tr>\n          <tr><td><strong>Cardiovasculaire</strong></td><td>Coronaropathie ; <span class=\"kw-clinique\">hypotension</span> orthostatique.</td></tr>\n          <tr><td><strong>Neurologique</strong></td><td><span class=\"kw-etio\">Épilepsie</span> (abaissement du seuil épileptogène) ; <span class=\"kw-ci\">maladie de Parkinson</span> — privilégier alors la <span class=\"kw-ttt\">clozapine</span>.</td></tr>\n          <tr><td><strong>Métabolique</strong></td><td><span class=\"kw-etio\">Diabète</span> ; <span class=\"kw-ci\">intolérance</span> au glucose (risque accru avec <span class=\"kw-ttt\">olanzapine</span> et <span class=\"kw-ttt\">clozapine</span>).</td></tr>\n          <tr><td><strong>Addictologique</strong></td><td><span class=\"kw-ttt\">Sevrage</span> de l'<span class=\"kw-etio\">alcool</span> (si prescription nécessaire → <span class=\"kw-ttt\">tiapride</span>), des barbituriques et des <span class=\"kw-ttt\">benzodiazépines</span>.</td></tr>\n          <tr><td><strong>Femme / sujet fragile</strong></td><td><span class=\"kw-ci\">Grossesse</span>, allaitement (se référer au CRAT). Précautions en cas d'<span class=\"kw-etio\">insuffisance cardiaque</span>, respiratoire, hépatique ou rénale.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant</em></p>","frequence":2},{"id":"74-5","rang":"B","rubrique":"Prise en charge","titre":"Antipsychotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés et/ou atteints de démence","contenu":"<p><strong>Voie d'administration</strong> — voie orale et voie IM disponibles pour la plupart des molécules. Des formes <strong>IM à libération prolongée</strong> (« formes retard ») existent : renouvelées toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-4 semaines</span>, elles améliorent l'<strong>observance</strong> mais ne sont possibles qu'<strong>après une période de stabilisation clinique</strong> sous traitement per os.</p>\n      <p><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span> :</strong></p>\n      <ul>\n        <li><strong>Clinique :</strong> périmètre abdominal ; IMC ; pression artérielle.</li>\n        <li><strong>Biologie :</strong> <span class=\"kw-bio\">NFS-plaquettes</span> ; <span class=\"kw-bio\">glycémie à jeun</span> ; <span class=\"kw-bio\">bilan lipidique</span> ; <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">urée</span> et <span class=\"kw-bio\">créatininémie</span> ; <span class=\"kw-bio\">prolactinémie</span> ; <span class=\"kw-bio\">β-HCG</span> chez la femme en âge de procréer.</li>\n        <li><strong><span class=\"kw-bio\">ECG</span> :</strong> recherche d'un trouble du rythme et d'un <span class=\"kw-alerte\">QTc long</span>.</li>\n        <li><strong><span class=\"kw-imagerie\">EEG</span> :</strong> en cas d'ATCD d'<span class=\"kw-etio\">épilepsie</span> ou de prescription de <span class=\"kw-ttt\">clozapine</span>.</li>\n      </ul>\n      <p><strong>Règles de prescription :</strong></p>\n      <ul>\n        <li>Information du patient : traitement à prendre <strong>tous <span class=\"kw-clinique\">les</span> jours</strong>, qui <span class=\"kw-alerte\">ne peut pas être arrêté brutalement</span>.</li>\n        <li>Débuter par un <strong>antipsychotique de 2ᵉ génération</strong> en 1ʳᵉ intention (la 1ʳᵉ génération reste une option, en particulier si succès antérieur).</li>\n        <li>Rechercher la <strong>posologie minimale efficace</strong> ; privilégier la <strong>monothérapie</strong>.</li>\n        <li>Ne <strong>pas associer 2 médicaments</strong> qui allongent le QT.</li>\n      </ul>\n      <p><strong>Durée du traitement :</strong> <span class=\"kw-chiffre\">≥ 2 ans</span> après la <span class=\"kw-clinique\">rémission</span> totale d'un 1ᵉʳ épisode psychotique ; <span class=\"kw-chiffre\">≥ 5 ans</span> après un 2ᵉ épisode ou une rechute.</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span></strong> — calendrier de <span class=\"kw-def\">suivi</span> métabolique et cardiaque :</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Avant</th><th><span class=\"kw-chiffre\">M1</span></th><th><span class=\"kw-chiffre\">M3</span></th><th>/trimestre</th><th>/an</th><th>/<span class=\"kw-chiffre\">5 ans</span></th></tr></thead>\n        <tbody>\n          <tr><td>Poids et IMC</td><td>X</td><td>X</td><td>X</td><td>X</td><td></td><td></td></tr>\n          <tr><td>Périmètre ombilical</td><td>X</td><td>X</td><td></td><td></td><td>X</td><td></td></tr>\n          <tr><td><span class=\"kw-bio\">Glycémie à jeun</span></td><td>X</td><td></td><td>X</td><td></td><td>X</td><td></td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan lipidique</span></td><td>X</td><td></td><td>X</td><td></td><td></td><td>X</td></tr>\n          <tr><td>Pression artérielle</td><td>X</td><td></td><td>X</td><td></td><td>X</td><td></td></tr>\n          <tr><td><span class=\"kw-bio\">ECG</span> (calcul du QTc)</td><td>X</td><td>X</td><td></td><td></td><td>X</td><td></td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"74-6","rang":"B","rubrique":"Prise en charge","titre":"Antipsychotiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> — Syndrome malin des neuroleptiques.</strong> Effet indésirable <strong>rare mais grave</strong>, décrit avec la plupart des molécules, qui <span class=\"kw-alerte\">engage le pronostic vital</span> : urgence diagnostique et thérapeutique.\n        <ul>\n          <li><strong>Installation :</strong> début rapidement progressif.</li>\n          <li><strong>Clinique :</strong> <span class=\"kw-clinique\">hyperthermie</span> (<span class=\"kw-chiffre\">40-41 °C</span>) ou <span class=\"kw-clinique\">hypothermie</span> (< 36 °C) ; <span class=\"kw-clinique\"><span class=\"kw-clinique\">sueurs</span></span> profuses ; dysautonomie (<span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span>, troubles cardio-respiratoires) ; <span class=\"kw-clinique\">rigidité extrapyramidale</span> ; troubles de la vigilance ; <span class=\"kw-clinique\">convulsions</span> possibles.</li>\n          <li><strong>Biologie :</strong> <span class=\"kw-bio\">hyperleucocytose</span> <span class=\"kw-chiffre\">> 15</span> 000/mm³ à PNN ; perturbations du <span class=\"kw-bio\">ionogramme</span> ; élévation des <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">ASAT</span> (lyse cellulaire).</li>\n          <li><strong>Prise en charge :</strong> transfert en <span class=\"kw-alerte\">réanimation</span> + <strong>arrêt du médicament</strong> (CI à vie) ; traitement non spécifique (rééquilibration hydro-électrolytique, lutte contre l'<span class=\"kw-clinique\">hyperthermie</span>) ; traitement spécifique = <span class=\"kw-ttt\">bromocriptine</span> (agoniste dopaminergique), amantadine, dantrolène.</li>\n        </ul>\n      </div>\n      <p>Principaux effets indésirables par type (d'après le collège) :</p>\n      <table >\n        <thead><tr><th>Effet indésirable</th><th>Génération</th><th>Gravité · fréquence</th><th><span class=\"kw-def\">Surveillance</span> / CAT</th></tr></thead>\n        <tbody>\n          <tr><td>Effets <span class=\"kw-alerte\">extrapyramidaux aigus</span> (dyskinésie, syndrome parkinsonien)</td><td>1ʳᵉ G (+++), 2ᵉ G (+)</td><td>+ · très fréquent</td><td>Injection IM d'anticholinergiques</td></tr>\n          <tr><td>Dyskinésies tardives (mâchonnement)</td><td>1ʳᵉ G (+++), 2ᵉ G (+)</td><td>++ · fréquent</td><td>Pas de traitement efficace</td></tr>\n          <tr><td><span class=\"kw-clinique\">Gynécomastie</span> / galactorrhée</td><td>1ʳᵉ G (+++), 2ᵉ G (++)</td><td>++ · fréquent</td><td>Surveiller le volume mammaire</td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome malin</span> des neuroleptiques</td><td>1ʳᵉ et 2ᵉ G</td><td>+++ · rare</td><td>Arrêt, transfert en <span class=\"kw-alerte\">réanimation</span></td></tr>\n          <tr><td>Trouble de la repolarisation (<span class=\"kw-alerte\">QT long</span>, <span class=\"kw-alerte\">torsade de pointes</span>)</td><td>1ʳᵉ et 2ᵉ G</td><td>+++ · assez fréquent</td><td><span class=\"kw-bio\">ECG</span> avant et pendant le traitement</td></tr>\n          <tr><td><span class=\"kw-alerte\">Agranulocytose</span></td><td><span class=\"kw-ttt\">Clozapine</span></td><td>+++ · rare</td><td><span class=\"kw-def\">Surveillance</span> régulière de la <span class=\"kw-bio\">NFS</span></td></tr>\n          <tr><td>Désordres métaboliques (poids, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">dyslipidémie</span>)</td><td>1ʳᵉ G (+), 2ᵉ G (+++)</td><td>++ · fréquent</td><td><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> ; <span class=\"kw-def\">surveillance</span> poids, <span class=\"kw-bio\">glycémie</span>, lipides</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Dyskinésies induites</strong> par <span class=\"kw-clinique\">les</span> antipsychotiques :</p>\n      <table >\n        <thead><tr><th></th><th>Akathisie</th><th>Dyskinésies précoces / aiguës</th><th>Dyskinésies tardives</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Moment</strong></td><td>—</td><td>À l'initiation ou au changement de posologie</td><td>Cures prolongées ; survenue imprévisible (mois à années)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>—</td><td>Sujets jeunes</td><td>Sujet âgé</td></tr>\n          <tr><td><strong>Manifestations</strong></td><td>Difficulté à rester immobile, impatiences, piétinement incessant</td><td>Contractures musculaires : crises oculogyres, protraction de la langue, <span class=\"kw-clinique\">trismus</span>, dystonie cervicale, opisthotonos</td><td>Dyskinésies bucco-facio-masticatoires : troubles de la phonation et de la déglutition, mauvais état dentaire</td></tr>\n          <tr><td><strong>Traitement</strong></td><td><span class=\"kw-ttt\">β-bloquant</span> non cardiosélectif, <span class=\"kw-ttt\">benzodiazépine</span>, adaptation de posologie</td><td>Injection d'<span class=\"kw-ttt\">anticholinergique</span> (tropatépine)</td><td>Difficiles à traiter, peuvent persister des années</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres effets indésirables</strong>, par appareil :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Psychiatriques</strong></td><td>Indifférence psychomotrice (passivité, émoussement affectif → diminuer la posologie ou changer de traitement) ; sédation ; <span class=\"kw-clinique\">confusion</span> (sujet âgé).</td></tr>\n          <tr><td><strong>Neurologiques</strong></td><td><span class=\"kw-etio\">AVC</span> ; crises convulsives iatrogènes (<span class=\"kw-ttt\">clozapine</span> la plus à risque) ; dyskinésies induites ; syndrome parkinsonien <span class=\"kw-etio\">iatrogène</span>.</td></tr>\n          <tr><td><strong>Métaboliques</strong></td><td>Prise de poids, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">syndrome métabolique</span> (surtout 2ᵉ génération) ; hyperprolactinémie (<span class=\"kw-ttt\">halopéridol</span>, sulpiride, phénothiazines) → <span class=\"kw-clinique\">gynécomastie</span>, galactorrhée.</td></tr>\n          <tr><td><strong>Neurovégétatifs</strong></td><td>Effets anticholinergiques (sécheresse buccale, <span class=\"kw-clinique\">constipation</span>, RAU, mydriase, glaucome) ; <span class=\"kw-clinique\">hypotension</span> orthostatique (effet adrénolytique).</td></tr>\n          <tr><td><strong>Cardiaques</strong></td><td>Allongement du QT → <span class=\"kw-alerte\">torsade de pointes</span>, <span class=\"kw-alerte\">FV</span>, <span class=\"kw-alerte\">mort subite</span>. QTc allongé si <span class=\"kw-chiffre\">> 450 ms</span> chez l'homme, <span class=\"kw-chiffre\">> 470 ms</span> chez la femme.</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Allergie</span> / <span class=\"kw-etio\">toxique</span></strong></td><td>Photosensibilisation (→ protection solaire systématique) ; <span class=\"kw-alerte\">agranulocytose</span> de la <span class=\"kw-ttt\">clozapine</span> → <span class=\"kw-bio\">NFS</span> hebdomadaire pendant <span class=\"kw-chiffre\">18 semaines</span> puis mensuelle.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Interactions médicamenteuses.</strong> Nombreuses : <strong>pharmacocinétiques</strong> (inducteurs ou inhibiteurs enzymatiques modifiant le métabolisme) et <strong>pharmacodynamiques</strong> (synergie des effets anticholinergiques, sédatifs, hypotenseurs).</div>","frequence":4},{"id":"74-7","rang":"A","rubrique":"Identifier une urgence","titre":"Antipsychotiques : connaître les modalités de prescription en situation d’urgence","contenu":"<p>En situation d'<span class=\"kw-alerte\">urgence</span> (état d'agitation, contexte psychotique aigu), <span class=\"kw-clinique\">les</span> modalités de prescription des antipsychotiques sont les suivantes :</p>\n      <ul>\n        <li>La voie <strong>per os doit être privilégiée</strong> ; la voie <span class=\"kw-ttt\">IM</span> n'est utilisée qu'en cas d'impossibilité de la voie orale.</li>\n        <li>Le recours à des antipsychotiques à visée <strong>sédative par voie IM</strong> doit être <strong>réservé aux états d'agitation sévères</strong>.</li>\n        <li><span class=\"kw-alerte\">Éviter l'escalade des doses</span> : risque d'effet cumulatif différé sur la vigilance.</li>\n        <li>Privilégier la <strong>monothérapie</strong>.</li>\n        <li>L'<strong><span class=\"kw-bio\">ECG</span> préalable</strong> reste indispensable, bien que parfois difficile à réaliser dans ces situations.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement</em></p>","frequence":2},{"id":"74-8","rang":"A","rubrique":"Définition","titre":"Antidépresseurs : connaître les principales classes et molécules","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-ttt\">antidépresseurs</span></strong> agissent en restaurant des concentrations en <span class=\"kw-def\">sérotonine</span> et en <span class=\"kw-def\">noradrénaline</span> proches de la normale, et stimulent la <span class=\"kw-etio\">neurogénèse</span>. Cette modulation se fait par <strong>3 voies</strong> : inhibition de la recapture présynaptique des neurotransmetteurs ; blocage des récepteurs présynaptiques α-adrénergiques ; inhibition de la dégradation par la <span class=\"kw-def\">monoamine oxydase A</span>.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">ISRS</span></strong></td><td>Inhibiteurs <strong>sélectifs</strong> de la recapture de la sérotonine</td><td><span class=\"kw-ttt\">Escitalopram</span> ; <span class=\"kw-ttt\">citalopram</span> ; <span class=\"kw-ttt\">sertraline</span> ; <span class=\"kw-ttt\">paroxétine</span> ; <span class=\"kw-ttt\">fluvoxamine</span> ; <span class=\"kw-ttt\">fluoxétine</span> (enfant / adolescent)</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">IRSNA</span></strong></td><td>Inhibiteurs de la recapture de la sérotonine <strong>et</strong> de la <span class=\"kw-ttt\">noradrénaline</span></td><td><span class=\"kw-ttt\">Venlafaxine</span> ; <span class=\"kw-ttt\">milnacipran</span></td></tr>\n          <tr><td><strong>Imipraminiques</strong> (tricycliques)</td><td>Inhibition <strong>moins sélective</strong> de la recapture des monoamines (sérotonine, <span class=\"kw-ttt\">noradrénaline</span>, <span class=\"kw-ttt\">dopamine</span>)</td><td><span class=\"kw-ttt\">Amitriptyline</span> ; <span class=\"kw-ttt\">clomipramine</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">IMAO</span></strong></td><td>Inhibiteurs de la monoamine oxydase A</td><td><span class=\"kw-ttt\">Moclobémide</span></td></tr>\n          <tr><td><strong>Autres antidépresseurs</strong></td><td>Mécanismes pharmacologiques différents</td><td><span class=\"kw-ttt\">Mirtazapine</span>, <span class=\"kw-ttt\">miansérine</span> : antagonistes des récepteurs α2-adrénergiques<br><span class=\"kw-ttt\">Agomélatine</span> : agoniste des récepteurs de la mélatonine, antagoniste des récepteurs 5HT2C</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"74-9","rang":"A","rubrique":"Prise en charge","titre":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","contenu":"<p><strong>Indications</strong> des antidépresseurs :</p>\n      <ul>\n        <li><strong>Troubles de l'humeur :</strong> <span class=\"kw-etio\">épisode dépressif caractérisé</span> (initiation et consolidation), trouble dépressif récurrent (phase de maintenance).</li>\n        <li><strong>Troubles anxieux :</strong> trouble anxieux généralisé, trouble panique, trouble phobique, <span class=\"kw-etio\">TSPT</span>, <span class=\"kw-etio\">TOC</span>.</li>\n        <li><strong>Douleurs neuropathiques</strong> (imipraminiques, IRSNA) ; <span class=\"kw-clinique\">céphalées</span> rebelles et migraines (imipraminiques, <span class=\"kw-ttt\">IMAO</span>).</li>\n        <li>Certains <strong>troubles du sommeil</strong> : narcolepsie avec cataplexie, énurésie.</li>\n      </ul>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span></strong> selon la classe :</p>\n      <table >\n        <thead><tr><th>Classe</th><th><span class=\"kw-ci\">CI absolues</span></th><th><span class=\"kw-ci\">CI relatives</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">ISRS</span> / IRSNA</strong></td><td>Association aux <span class=\"kw-ttt\">IMAO</span> ; <span class=\"kw-ci\">hypersensibilité</span></td><td><span class=\"kw-ci\">Grossesse</span>, allaitement (bénéfice-risque) ; insuffisance hépatique et rénale (ajustement des posologies)</td></tr>\n          <tr><td><strong>Imipraminiques</strong></td><td>Association aux <span class=\"kw-ttt\">IMAO</span> ; <span class=\"kw-ci\">hypersensibilité</span> ; <span class=\"kw-ci\">glaucome à angle fermé</span> et <span class=\"kw-ci\">adénome de prostate</span> (effets anticholinergiques) ; CI cardiovasculaires : <span class=\"kw-etio\">IDM</span> récent, <span class=\"kw-etio\">SCA</span> non stabilisé, trouble du rythme, <span class=\"kw-etio\">insuffisance cardiaque</span> décompensée</td><td><span class=\"kw-ci\">Grossesse</span>, allaitement ; crise épileptique ; insuffisance hépatique et rénale ; âge <span class=\"kw-chiffre\">> 75 ans</span> ; trouble démentiel</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">IMAO</span></strong></td><td>Association aux <span class=\"kw-ttt\">IMAO</span> ; <span class=\"kw-ci\">hypersensibilité</span> ; <span class=\"kw-etio\">HTA</span> ; phéochromocytome ; <span class=\"kw-etio\">AVC</span> ; polynévrites</td><td><span class=\"kw-ci\">Grossesse</span>, allaitement ; alimentation riche en <span class=\"kw-alerte\">tryptophane et tyramine</span> (fromage fermenté, sauce soja, hareng en saumure, bière, vin)</td></tr>\n          <tr><td><strong>Agomélatine</strong></td><td>Association aux <span class=\"kw-ttt\">IMAO</span> ; <span class=\"kw-ci\">hypersensibilité</span> ; <span class=\"kw-ci\">insuffisance hépatique</span></td><td><span class=\"kw-ci\">Grossesse</span>, allaitement (bénéfice-risque)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> potentielle.</strong> L'association d'un traitement par <span class=\"kw-ttt\">IMAO</span> à un autre antidépresseur augmente fortement le risque de <span class=\"kw-alerte\">syndrome sérotoninergique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 99 — <span class=\"kw-etio\">Migraine</span> - névralgie trijumeau - algie face</em></p>","frequence":0},{"id":"74-10","rang":"B","rubrique":"Prise en charge","titre":"Antidépresseurs : connaître les règles de bon usage à tous les âges de la vie, notamment chez les enfants/adolescents et les patients âgés","contenu":"<div class=\"callout callout-warn\"><strong>Délai d'action.</strong> Le délai d'action des antidépresseurs est de <span class=\"kw-chiffre\">2-4 semaines</span> quelle que soit la classe : ce n'est <strong>jamais un traitement d'<span class=\"kw-alerte\">urgence</span></strong>. Ne pas interrompre un traitement avant <span class=\"kw-chiffre\">4 semaines</span> à posologie efficace en l'absence d'amélioration. Une réponse <strong>trop rapide</strong> doit faire évoquer un <span class=\"kw-alerte\">virage maniaque</span> de l'humeur, et donc un <span class=\"kw-etio\">trouble bipolaire</span>.</div>\n      <p><strong>Durée du traitement après <span class=\"kw-clinique\">rémission</span> d'un <span class=\"kw-etio\">épisode dépressif caractérisé</span> :</strong></p>\n      <ul>\n        <li>1ᵉʳ épisode : <span class=\"kw-chiffre\">6 à 8 mois</span>.</li>\n        <li>2ᵉ épisode : <span class=\"kw-chiffre\">12 mois</span>.</li>\n        <li>3ᵉ épisode et au-delà : <span class=\"kw-chiffre\">24 mois</span>.</li>\n      </ul>\n      <p><strong>Troubles anxieux :</strong> la réponse complète est obtenue après <span class=\"kw-chiffre\">4 à 8 semaines</span>. Exemple du <span class=\"kw-etio\">TOC</span> : délai d'action de <span class=\"kw-chiffre\">4-8 semaines</span>, réponse maximale à<span class=\"kw-chiffre\"> 10-12 semaines</span> ; poursuivre <span class=\"kw-chiffre\">≥ 3 mois</span> à posologie efficace avant de conclure à l'inefficacité. <span class=\"kw-clinique\">Les</span> posologies sont débutées plus bas dans les troubles anxieux, mais parfois plus élevées que dans l'EDC.</p>\n      <p><strong>Modalités d'arrêt :</strong> diminution <strong>progressive</strong> des posologies pour éviter un <strong>syndrome d'arrêt</strong> — il survient dans la semaine suivant l'arrêt, dure < 1 semaine (anxiété, irritabilité, troubles du sommeil, <span class=\"kw-clinique\"><span class=\"kw-clinique\">vertiges</span></span>, troubles neurosensoriels, syndrome pseudo-grippal).</p>\n      <p><strong>Choix de la classe :</strong> la <strong>monothérapie</strong> est privilégiée ; <span class=\"kw-ttt\">ISRS</span> ou <span class=\"kw-ttt\">IRSNA</span> en 1ʳᵉ intention ; imipraminiques ou <span class=\"kw-ttt\">IMAO</span> en 3ᵉ-4ᵉ intention. En cas de résistance : augmentation de posologie, changement d'antidépresseur, adjonction d'un thymorégulateur — <strong>pas d'association de <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> an</span>tidépresseurs</strong> (risque de syndrome sérotoninergique).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Adaptation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sujet âgé</strong></td><td>Posologie initiale <strong>réduite de <span class=\"kw-chiffre\">50 %</span></strong>, puis augmentation progressive des doses.</td></tr>\n          <tr><td><strong>Enfant / adolescent</strong></td><td><span class=\"kw-ttt\">Fluoxétine</span> ; <span class=\"kw-def\">surveillance</span> <strong>rapprochée du risque suicidaire</strong> à l'initiation.</td></tr>\n        </tbody>\n      </table>","frequence":3},{"id":"74-11","rang":"A","rubrique":"Prise en charge","titre":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","contenu":"<p><strong>Effets indésirables principaux :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Virage de l'humeur</span> : apparition d'un syndrome maniaque ou de caractéristiques mixtes.</li>\n        <li><span class=\"kw-alerte\">Aggravation des idées suicidaires</span>, possible à l'initiation du traitement — expliquée par la dissociation entre un <strong>effet rapide sur l'inhibition psychomotrice</strong> et un <strong>effet retardé sur la tristesse de l'humeur</strong>. Survient surtout chez <span class=\"kw-clinique\">les</span> sujets jeunes (<span class=\"kw-chiffre\">< 24 ans</span>) : à surveiller, en particulier chez l'adolescent.</li>\n      </ul>\n      <p><strong>Autres effets :</strong> majoration transitoire de l'<span class=\"kw-clinique\">anxiété</span> les premiers jours ; effets indésirables sexuels (libido, érection) parfois tardifs et durables ; prise de poids ; effets bénins fréquents (digestifs, tremblements) précoces, dose-dépendants et transitoires. Chez le <strong>sujet âgé</strong>, surveiller les troubles de l'équilibre et la <span class=\"kw-bio\">natrémie</span> (risque d'<span class=\"kw-alerte\">hyponatrémie par SIADH</span>).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-ttt\">ISRS</span></th><th>IRSNA</th><th>Tricycliques</th></tr></thead>\n        <tbody>\n          <tr><td>Hyponatrémie par <span class=\"kw-bio\">SIADH</span> ; <span class=\"kw-def\">syndrome extrapyramidal</span> ; allongement du QT ; interactions (cytochrome P450) ; thrombopathie</td><td>Hypotension ; <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span> ; effets anticholinergiques minimes ; <span class=\"kw-ttt\">venlafaxine</span> → poussée d'<span class=\"kw-etio\">HTA</span> ; allongement du QT</td><td>Allongement du QT ; effets anticholinergiques ; effet adrénergique ; effet stabilisant de membrane ; <span class=\"kw-def\">syndrome pyramidal</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Urgence — Syndrome sérotoninergique.</strong> Effet indésirable rare mais grave, lié à un excès de sérotonine.\n        <ul>\n          <li><strong>Toxiques en cause :</strong> antidépresseurs sérotoninergiques, <span class=\"kw-ttt\">tramadol</span>, amphétamines (MDMA), cocaïne, <span class=\"kw-ttt\">lithium</span>, triptans, millepertuis.</li>\n          <li><strong>Signes neurologiques :</strong> <span class=\"kw-clinique\">confusion</span>, hallucinations, akathisie, tremblements, <span class=\"kw-alerte\">myoclonies +++</span>, rigidité, <span class=\"kw-def\">syndrome pyramidal</span>, hyperréflexie, <span class=\"kw-clinique\">mydriase bilatérale</span>.</li>\n          <li><strong>Signes neuro-végétatifs :</strong> <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-etio\">HTA</span> ou hypotension, <span class=\"kw-clinique\">hyperthermie</span> (<span class=\"kw-chiffre\">40-43 °C</span>), sudation, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">tachypnée</span>.</li>\n          <li><strong>Risques :</strong> choc, <span class=\"kw-clinique\">coma</span> agité, rhabdomyolyse, <span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-etio\">IRA</span> fonctionnelle.</li>\n          <li><strong>Prise en charge :</strong> arrêt du médicament, transfert en réanimation, traitement non spécifique, antagoniste sérotoninergique = <span class=\"kw-ttt\">cyproheptadine</span>.</li>\n        </ul>\n      </div>\n      <p>Le syndrome sérotoninergique est à <strong>distinguer du syndrome malin des neuroleptiques</strong> :</p>\n      <table >\n        <thead><tr><th></th><th>Syndrome malin des neuroleptiques</th><th>Syndrome sérotoninergique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cause</strong></td><td><span class=\"kw-ttt\">Antipsychotiques</span></td><td><span class=\"kw-ttt\">Antidépresseurs</span></td></tr>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Hyperthermie</span> ; <span class=\"kw-clinique\">sueurs</span> ; <span class=\"kw-clinique\">rigidité extrapyramidale</span> ; troubles de la vigilance ; <span class=\"kw-clinique\">convulsions</span></td><td>Signes digestifs ; neurologiques (myoclonies, hyperréflexie, mydriase) ; neuro-végétatifs</td></tr>\n          <tr><td><strong>Traitement spécifique</strong></td><td><span class=\"kw-ttt\">Bromocriptine</span> (amantadine, dantrolène)</td><td><span class=\"kw-ttt\">Cyproheptadine</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span></em></p>","frequence":0},{"id":"74-12","rang":"A","rubrique":"Définition","titre":"Anxiolytiques : connaître les principales classes et molécules","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-ttt\">benzodiazépines</span> (BZD)</strong> sont la <strong>principale classe d'anxiolytique</strong>. Mécanisme : elles facilitent la <span class=\"kw-etio\">transmission GABAergique</span> en activant le récepteur <strong>GABA-A</strong>, ce qui diminue l'hyperexcitabilité neuronale liée à l'anxiété.</p>\n      <table >\n        <thead><tr><th>BZD anxiolytiques</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Demi-vie courte</strong></td><td><span class=\"kw-ttt\">Oxazépam</span> — métabolite final de nombreuses BZD, demi-vie la plus courte, à <strong>privilégier</strong> chez l'insuffisant hépatique, la personne âgée et la femme enceinte ; <span class=\"kw-ttt\">lorazépam</span></td></tr>\n          <tr><td><strong>Demi-vie longue</strong></td><td><span class=\"kw-ttt\">Alprazolam</span> ; <span class=\"kw-ttt\">diazépam</span></td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong>anxiolytiques non <span class=\"kw-ttt\">benzodiazépines</span></strong> ont pour principal avantage l'<strong>absence de risque de dépendance</strong> :</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécule</th><th>Aspects pratiques</th><th><span class=\"kw-ci\">CI absolues</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Antihistaminique</strong> (antagoniste <span class=\"kw-chiffre\">H1</span>)</td><td><span class=\"kw-ttt\">Hydroxyzine</span> (Atarax®)</td><td>Anxiolyse moindre qu'avec <span class=\"kw-clinique\">les</span> BZD ; anxiolytique de <strong>choix chez l'enfant</strong> ; efficacité dès la 1ʳᵉ prise ; pas de dépendance ; effets anticholinergiques ; allongement du QT</td><td><span class=\"kw-ci\">Glaucome à angle fermé</span> ; <span class=\"kw-ci\">adénome prostatique</span> ; QT long ; début de <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-ci\">hypersensibilité</span></td></tr>\n          <tr><td><strong>β-bloquant</strong></td><td><span class=\"kw-ttt\">Propranolol</span> (Avlocardyl®)</td><td>Efficacité dès la 1ʳᵉ prise ; traite <span class=\"kw-clinique\">les</span> manifestations physiques de l'anxiété ; risque de <span class=\"kw-clinique\">bradycardie</span> et d'<span class=\"kw-clinique\">hypotension</span></td><td><span class=\"kw-ci\">Asthme</span> et <span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">insuffisance cardiaque</span> non contrôlée ; <span class=\"kw-etio\">choc cardiogénique</span> ; BAV 2-3 non appareillés ; <span class=\"kw-clinique\">angor</span> de Prinzmetal ; maladie du sinus ; <span class=\"kw-clinique\">bradycardie</span> ; phéochromocytome</td></tr>\n          <tr><td><strong>Autre</strong></td><td><span class=\"kw-ttt\">Buspirone</span> (Buspar®)</td><td>Agoniste 5HT1A ; action <strong>retardée</strong> (après <span class=\"kw-chiffre\">1 semaine</span>) ; anxiolyse moindre qu'avec <span class=\"kw-clinique\">les</span> BZD ; pas de dépendance</td><td><span class=\"kw-ci\">Hypersensibilité</span> ; association à un <span class=\"kw-ttt\">IMAO</span></td></tr>\n        </tbody>\n      </table>\n      <p>Disposent aussi d'un effet anxiolytique : <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antidépresseurs</span> (traitement de fond des troubles anxieux) et les <span class=\"kw-ttt\">antipsychotiques</span> sédatifs (cyamémazine, lévomépromazine — intérêt dans le traitement symptomatique de courte durée de l'anxiété de l'adulte si échec des traitements habituels).</p>","frequence":0},{"id":"74-13","rang":"A","rubrique":"Prise en charge","titre":"Anxiolytiques : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients âgés","contenu":"<p><strong>Indications des <span class=\"kw-ttt\">benzodiazépines</span> :</strong></p>\n      <ul>\n        <li>Manifestations <span class=\"kw-clinique\">anxieuses</span> intenses et/ou invalidantes (traitement symptomatique).</li>\n        <li>Prévention du <span class=\"kw-alerte\">syndrome de sevrage en alcool</span> (delirium tremens).</li>\n        <li>Traitement des <span class=\"kw-clinique\">crises convulsives</span> et des épilepsies (partielles ou généralisées).</li>\n        <li>Douleur neuropathique.</li>\n        <li>Insomnie aiguë transitoire.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-ci\">CI absolues</span></th><th><span class=\"kw-ci\">CI relatives</span></th></tr></thead>\n        <tbody>\n          <tr><td>\n            <span class=\"kw-ci\">Hypersensibilité</span> connue<br>\n            <span class=\"kw-ci\">Insuffisance respiratoire sévère</span><br>\n            <span class=\"kw-ci\">Insuffisance hépatique</span> (<strong>sauf <span class=\"kw-ttt\">oxazépam</span></strong>)<br>\n            <span class=\"kw-ci\">SAOS</span> non traité par PPC<br>\n            Myasthénie<br>\n            <span class=\"kw-ci\">Enfant < 15 ans</span> (zolpidem, zopiclone)\n          </td><td>\n            Grossesse, allaitement<br>\n            Insuffisance rénale<br>\n            ATCD de troubles affectifs<br>\n            ATCD de réaction paradoxale\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Associations.</strong> Aucune association n'est formellement <span class=\"kw-ci\">contre-indiquée</span> avec les BZD ; des précautions s'imposent en cas d'association à d'autres médicaments <strong>sédatifs</strong> (potentialisation des effets).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 105 — Epilepsie</em></p>","frequence":2},{"id":"74-14","rang":"A","rubrique":"Prise en charge","titre":"Anxiolytiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","contenu":"<p><strong>Règles de bon usage des anxiolytiques (BZD) :</strong></p>\n      <ul>\n        <li>Voie <strong>orale</strong> privilégiée. <strong>Pas de bilan paraclinique pré-thérapeutique</strong> systématique : l'interrogatoire et la clinique éliminent <span class=\"kw-clinique\">les</span> CI et anticipent les interactions.</li>\n        <li>Prescription à la <strong>dose minimale efficace</strong>, en respectant <span class=\"kw-clinique\">les</span> posologies recommandées.</li>\n        <li><span class=\"kw-alerte\">Ne pas associer 2 benzodiazépines</span>, même pour des indications différentes.</li>\n        <li>L'<strong>arrêt doit toujours être progressif</strong> (risque de <span class=\"kw-clinique\">crise convulsive</span> si arrêt brutal), sur une durée adaptée à celle du traitement.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Item</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Patient <span class=\"kw-chiffre\">≥ 65 ans</span></strong></td><td>Traitement par BZD non reconductible <span class=\"kw-chiffre\">> 4 semaines</span> sans <span class=\"kw-def\">réévaluation</span> médicale (date d'arrêt stipulée au patient et consignée dans le dossier) ; posologies d'initiation <strong>divisées par 2</strong>.</td></tr>\n          <tr><td><strong>Durée maximale réglementaire</strong></td><td>Anxiolytique <span class=\"kw-chiffre\">≤ 12 semaines</span> (période de <span class=\"kw-ttt\">sevrage</span> incluse) ; hypnotique <span class=\"kw-chiffre\">≤ 4 semaines</span>.</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"74-15","rang":"A","rubrique":"Prise en charge","titre":"Anxiolytiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","contenu":"<table >\n        <thead><tr><th>Effet indésirable</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Dépendance</span></strong> <em>(EI principal)</em></td><td>Associe une <strong>perte d'efficacité</strong> du traitement à la posologie prescrite (tolérance pharmacologique) et un <strong>syndrome de <span class=\"kw-ttt\">sevrage</span></strong> à l'arrêt, surtout si arrêt brutal.</td></tr>\n          <tr><td><strong>Sédation</strong></td><td>Somnolence diurne, <span class=\"kw-clinique\">asthénie</span>, sensation vertigineuse, altération de la vigilance → précautions pour la <span class=\"kw-alerte\">conduite automobile</span> ; effets potentialisés par l'<span class=\"kw-etio\">alcool</span> et <span class=\"kw-clinique\">les</span> autres sédatifs.</td></tr>\n          <tr><td><strong>Comportement</strong></td><td>Effet <strong>désinhibiteur</strong> ; <span class=\"kw-clinique\">réactions paradoxales</span> (agitation, agressivité), favorisées par l'<span class=\"kw-etio\">alcool</span> et fréquentes chez <span class=\"kw-clinique\">les</span> adolescents.</td></tr>\n          <tr><td><strong>Cognition</strong></td><td>Altération de la <span class=\"kw-clinique\">mémoire</span> ; actes automatiques amnésiques (amnésie antérograde, conséquences médico-légales possibles) ; <span class=\"kw-clinique\">confusion</span> possible chez le sujet âgé.</td></tr>\n          <tr><td><strong>Rebond</strong></td><td>À l'arrêt du traitement : réapparition de symptômes anxieux ou d'insomnie plus intenses, diminuant en quelques jours.</td></tr>\n          <tr><td><strong>Sujet âgé</strong></td><td>Risque de <span class=\"kw-clinique\">confusion</span>, de <span class=\"kw-alerte\">chutes</span> et de fractures (sédation + effets cérébelleux).</td></tr>\n        </tbody>\n      </table>\n      <p>Sur le plan des <strong>interactions</strong>, aucune association n'est formellement <span class=\"kw-ci\">contre-indiquée</span>, mais l'association à d'autres médicaments <strong>sédatifs</strong> (<span class=\"kw-etio\">alcool</span> inclus) potentialise la <span class=\"kw-etio\">dépression</span> du système nerveux central.</p>","frequence":2},{"id":"74-16","rang":"A","rubrique":"Prise en charge","titre":"Anxiolytiques : connaître les modalités de prescription en situation d’urgence","contenu":"<p>En situation d'<span class=\"kw-alerte\">urgence</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">benzodiazépines</span> sont utilisées pour : un état d'<span class=\"kw-clinique\">agitation</span>, des <span class=\"kw-clinique\">crises convulsives</span> ou un <span class=\"kw-etio\">état de mal épileptique</span>, et la prévention ou le traitement du <span class=\"kw-alerte\">syndrome de sevrage alcoolique</span> (delirium tremens).</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Orale</strong></td><td>À privilégier.</td></tr>\n          <tr><td><strong>IM</strong></td><td>Si la voie orale est impossible. Molécules disponibles : <span class=\"kw-ttt\">diazépam</span>, <span class=\"kw-ttt\">clorazépate dipotassique</span>, <span class=\"kw-ttt\">clonazépam</span>. Inconvénient : résorption incomplète, distribution lente et irrégulière.</td></tr>\n          <tr><td><strong>IV lente</strong></td><td>Rarement utilisée mais possible pour certaines molécules (notamment dans l'<strong><span class=\"kw-etio\">état de mal épileptique</span></strong>). Augmente le risque de <span class=\"kw-alerte\">dépression respiratoire</span> → à réaliser avec un <strong>plateau technique de <span class=\"kw-alerte\">réanimation</span> à proximité</strong>.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"74-17","rang":"A","rubrique":"Définition","titre":"Hypnotiques : connaître les principales classes et molécules","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-ttt\">hypnotiques</span></strong> sont des psychotropes induisant le sommeil. Molécules proches des anxiolytiques, leurs propriétés anxiolytiques et sédatives favorisent l'endormissement en réduisant les manifestations anxieuses du soir.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong>BZD hypnotiques</strong></td><td><span class=\"kw-ttt\">Lormétazépam</span> ; <span class=\"kw-ttt\">loprazolam</span> ; <span class=\"kw-ttt\">nitrazépam</span> ; <span class=\"kw-ttt\">estazolam</span></td></tr>\n          <tr><td><strong>Apparentés aux BZD</strong> <em>(« médicaments en Z »)</em></td><td><span class=\"kw-ttt\">Zolpidem</span> ; <span class=\"kw-ttt\">zopiclone</span></td></tr>\n          <tr><td><strong>Antihistaminiques</strong> <em>(passant la barrière hémato-encéphalique)</em></td><td><span class=\"kw-ttt\">Doxylamine</span> ; <span class=\"kw-ttt\">alimémazine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La <span class=\"kw-ttt\">mélatonine</span> ne doit <strong>pas</strong> être considérée comme un hypnotique.</div>","frequence":0},{"id":"74-18","rang":"A","rubrique":"Prise en charge","titre":"Hypnotiques : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients âgés","contenu":"<div class=\"callout callout-warn\"><strong>Indication unique.</strong> <span class=\"kw-clinique\">Les</span> hypnotiques n'ont qu'une seule indication : l'<strong>insomnie aiguë transitoire</strong>. Il n'existe <span class=\"kw-alerte\">aucune indication pour l'insomnie chronique</span>.</div>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span></strong> — identiques à celles des <span class=\"kw-ttt\">benzodiazépines</span> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-ci\">CI absolues</span></th><th><span class=\"kw-ci\">CI relatives</span></th></tr></thead>\n        <tbody>\n          <tr><td>\n            <span class=\"kw-ci\">Hypersensibilité</span> connue<br>\n            <span class=\"kw-ci\">Insuffisance respiratoire sévère</span><br>\n            <span class=\"kw-ci\">Insuffisance hépatique</span> (sauf <span class=\"kw-ttt\">oxazépam</span>)<br>\n            <span class=\"kw-ci\">SAOS</span> non traité par PPC<br>\n            Myasthénie<br>\n            <span class=\"kw-ci\">Enfant < 15 ans</span> (zolpidem, zopiclone)\n          </td><td>\n            Grossesse, allaitement<br>\n            Insuffisance rénale<br>\n            ATCD de troubles affectifs<br>\n            ATCD de réaction paradoxale\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 110 — Trouble sommeil</em></p>","frequence":0},{"id":"74-19","rang":"A","rubrique":"Prise en charge","titre":"Hypnotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","contenu":"<table >\n        <thead><tr><th>Règle</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Durée maximale</strong></td><td>Hypnotique <span class=\"kw-chiffre\">≤ 4 semaines</span> (période de <span class=\"kw-ttt\">sevrage</span> incluse).</td></tr>\n          <tr><td><strong>Pas d'association</strong></td><td><span class=\"kw-alerte\">Pas d'association de 2 hypnotiques</span> pour le traitement d'une insomnie.</td></tr>\n          <tr><td><strong>Zolpidem</strong></td><td>Prescription sur <strong>ordonnance sécurisée</strong> : nombre d'unités par prise, nombre de prises et dosage écrits <strong>en toutes lettres</strong> ; absence de chevauchement sauf mention contraire.</td></tr>\n          <tr><td><strong>Patient <span class=\"kw-chiffre\">≥ 65 ans</span></strong></td><td>Posologie d'initiation <strong>divisée par 2</strong> ; <span class=\"kw-def\">réévaluation</span> rapprochée.</td></tr>\n          <tr><td><strong>Arrêt</strong></td><td>Toujours <strong>progressif</strong>, sur une durée adaptée.</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"74-20","rang":"A","rubrique":"Prise en charge","titre":"Hypnotiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","contenu":"<p>Le profil d'effets indésirables des hypnotiques est <strong>identique à celui des <span class=\"kw-ttt\">benzodiazépines</span> anxiolytiques</strong> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Dépendance</span> : perte d'efficacité du traitement et syndrome de <span class=\"kw-ttt\">sevrage</span> à l'arrêt.</li>\n        <li><strong>Sédation diurne</strong> : somnolence, <span class=\"kw-clinique\">asthénie</span>, altération de la vigilance.</li>\n        <li>Altération de la <span class=\"kw-clinique\">mémoire</span> et de la cognition ; actes automatiques amnésiques.</li>\n        <li><strong>Rebond de l'insomnie</strong> à l'arrêt du traitement.</li>\n        <li>Réactions paradoxales (agitation, agressivité), effet désinhibiteur.</li>\n        <li>Chez le <strong>sujet âgé</strong> : <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-alerte\">chutes</span> et fractures.</li>\n      </ul>\n      <p>Sur le plan des <strong>interactions</strong>, des précautions s'imposent en cas d'association à d'autres médicaments sédatifs, <span class=\"kw-etio\">alcool</span> inclus (potentialisation).</p>","frequence":0},{"id":"74-21","rang":"A","rubrique":"Définition","titre":"Thymorégulateurs : connaître les principales classes et molécules","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-ttt\">thymorégulateurs</span></strong> (ou normothymiques, thymoisoleptiques) sont des stabilisateurs de l'humeur : ils diminuent la <strong>fréquence, la durée et l'intensité</strong> des épisodes thymiques (maniaques ou dépressifs).</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Lithium</span></strong></td><td>Carbonate de <span class=\"kw-ttt\">lithium</span> (Téralithe®) — <strong>traitement de référence</strong> des troubles bipolaires.</td></tr>\n          <tr><td><strong>Antiépileptiques</strong></td><td><span class=\"kw-ttt\">Acide valproïque</span> ; <span class=\"kw-ttt\">valpromide</span> ; <span class=\"kw-ttt\">carbamazépine</span> ; <span class=\"kw-ttt\">lamotrigine</span>.</td></tr>\n          <tr><td><strong>Antipsychotiques de 2ᵉ génération</strong></td><td>Ex. <span class=\"kw-ttt\">olanzapine</span> — action thymorégulatrice par régulation de la <span class=\"kw-ttt\">dopamine</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>L'approche pharmacologique du <span class=\"kw-etio\">trouble bipolaire</span> est <strong>double</strong> : traiter <span class=\"kw-clinique\">les</span> <strong>accès aigus</strong> (antipsychotiques pour l'accès maniaque, antidépresseurs avec prudence pour l'épisode dépressif) et <strong>modifier le cours évolutif</strong> de la maladie en prévenant la récidive des accès (traitement de fond).</p>","frequence":1},{"id":"74-22","rang":"B","rubrique":"Prise en charge","titre":"Thymorégulateurs : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients","contenu":"<p><strong>Indications</strong> des thymorégulateurs :</p>\n      <ul>\n        <li>Traitement <strong>curatif</strong> de l'épisode maniaque ou dépressif caractérisé dans le cadre d'un <span class=\"kw-etio\">trouble bipolaire</span>.</li>\n        <li>Traitement <strong>préventif</strong> de la récidive dans le <span class=\"kw-etio\">trouble bipolaire</span> et le <span class=\"kw-etio\">trouble schizo-affectif</span>.</li>\n      </ul>\n      <p><strong>Lithium</strong> — <span class=\"kw-ci\">contre-indications</span> et <span class=\"kw-ci\">bilan pré-thérapeutique</span> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-ci\">CI absolues</span></th><th><span class=\"kw-ci\">CI relatives</span></th><th>Bilan pré-thérapeutique</th></tr></thead>\n        <tbody>\n          <tr><td>\n            <span class=\"kw-ci\">Insuffisance rénale</span> même modérée (<span class=\"kw-bio\">clairance</span> <span class=\"kw-chiffre\">< 85 mL/min</span>)<br>\n            Déplétion hydrosodée, hyponatrémie, régime sans sel, association aux <span class=\"kw-ci\">diurétiques</span><br>\n            Coronaropathie sévère, <span class=\"kw-etio\">insuffisance cardiaque</span> instable<br>\n            Allaitement\n          </td><td>\n            <span class=\"kw-etio\">HTA</span><br>\n            <span class=\"kw-etio\">Épilepsie</span><br>\n            <span class=\"kw-etio\">Hypothyroïdie</span><br>\n            Grossesse 1ᵉʳ trimestre (risque de cardiopathie congénitale)\n          </td><td>\n            <span class=\"kw-bio\">NFS-plaquettes</span> ; <span class=\"kw-bio\">glycémie à jeun</span><br>\n            Bilan rénal : <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, urémie, <span class=\"kw-bio\">clairance</span>, <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">glycosurie</span><br>\n            Bilan phospho-calcique ; <span class=\"kw-bio\">TSH</span> ; <span class=\"kw-bio\">ECG</span><br>\n            <span class=\"kw-bio\">β-HCG</span> + contraception efficace (risque tératogène)<br>\n            <span class=\"kw-imagerie\">EEG</span> si ATCD d'<span class=\"kw-etio\">épilepsie</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Antiépileptiques thymorégulateurs</strong> — <span class=\"kw-ci\">contre-indications</span> :</p>\n      <table >\n        <thead><tr><th></th><th>Carbamazépine</th><th>Valproate / valpromide</th><th>Lamotrigine</th></tr></thead>\n        <tbody>\n          <tr><td><strong>CI absolues</strong></td><td>Hypersensibilité ; association aux <span class=\"kw-ttt\">IMAO</span> ; troubles de la conduction (BAV) ; ATCD de porphyrie aiguë intermittente ; ATCD d'aplasie médullaire ; insuffisance hépatique sévère ; grossesse, allaitement</td><td>Hypersensibilité ; <span class=\"kw-etio\">hépatite</span> aiguë ou chronique ; ATCD personnel ou familial d'<span class=\"kw-etio\">hépatite</span> sévère ; porphyrie hépatique ; grossesse, allaitement ; <span class=\"kw-ci\">femme en âge de procréer</span></td><td>Hypersensibilité ; ATCD de toxidermie à la <span class=\"kw-ttt\">lamotrigine</span> (syndrome de Stevens-Johnson, syndrome de Lyell)</td></tr>\n          <tr><td><strong>CI relatives</strong></td><td>Glaucome à angle fermé ; adénome de prostate</td><td>Association à la <span class=\"kw-ttt\">lamotrigine</span></td><td>ATCD d'allergie ou d'éruptions avec d'autres antiépileptiques</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span></em></p>","frequence":2},{"id":"74-23","rang":"B","rubrique":"Prise en charge","titre":"Thymorégulateurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","contenu":"<p><strong>Lithium</strong> — effets indésirables par appareil :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Neuropsychiques</strong></td><td>Tremblements (fréquents) ; signes extrapyramidaux ; troubles du sommeil, somnolence diurne ; ralentissement psychomoteur, faiblesse musculaire</td></tr>\n          <tr><td><strong>Endocriniens</strong></td><td><span class=\"kw-etio\">Hypothyroïdie</span>, goitre ; prise de poids ; hyperparathyroïdie, hypercalcémie</td></tr>\n          <tr><td><strong>Rénaux</strong></td><td><span class=\"kw-alerte\">Diabète insipide néphrogénique</span> → syndrome polyuro-polydipsique ; glomérulopathie extra-membraneuse → <span class=\"kw-etio\">syndrome néphrotique</span> ; néphropathie tubulo-interstitielle</td></tr>\n          <tr><td><strong>Digestifs</strong></td><td><span class=\"kw-clinique\">Nausées</span>, dysgueusie, <span class=\"kw-clinique\">diarrhée</span>, gastralgies</td></tr>\n          <tr><td><strong>Cardiovasculaires</strong></td><td>Troubles de la conduction, du rythme, de la repolarisation (→ <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">ECG</span>) ; myocardites</td></tr>\n          <tr><td><strong>Hématologiques / cutanés</strong></td><td>Hyperleucocytose avec lymphopénie ; acné, <span class=\"kw-clinique\">psoriasis</span>, <span class=\"kw-clinique\">rash</span>, <span class=\"kw-clinique\">prurit</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Lithium — interactions médicamenteuses :</strong></p>\n      <ul>\n        <li><strong>Augmentation</strong> de la lithiémie : <span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">diurétiques</span>, <span class=\"kw-ci\">IEC</span>, <span class=\"kw-ci\">ARA2</span>.</li>\n        <li><strong>Diminution</strong> de la lithiémie : <span class=\"kw-ttt\">corticoïdes</span>, mannitol.</li>\n        <li>Risque de <span class=\"kw-alerte\">neurotoxicité</span> en association avec la <span class=\"kw-ttt\">carbamazépine</span>.</li>\n        <li>Majoration du risque de syndrome malin des neuroleptiques et de syndrome sérotoninergique.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> — Surdosage au <span class=\"kw-ttt\">lithium</span>.</strong> La <strong>fenêtre thérapeutique est étroite</strong> : toxicité si lithiémie <span class=\"kw-chiffre\">> 1,5 mEq/L</span>.\n        <ul>\n          <li><strong>Circonstances :</strong> prise d'<span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">IEC</span> / <span class=\"kw-ttt\">ARA2</span> / <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-clinique\">déshydratation</span>, régime hyposodé, <span class=\"kw-ci\">insuffisance rénale</span>, intoxication médicamenteuse volontaire.</li>\n          <li><strong>Clinique :</strong> <span class=\"kw-alerte\">syndrome cérébelleux</span> (tremblements, <span class=\"kw-clinique\">dysarthrie</span>, ataxie) ; myoclonies ; <span class=\"kw-clinique\">confusion</span>, somnolence, <span class=\"kw-clinique\">convulsions</span> ; troubles de la conduction cardiaque.</li>\n          <li><strong>Prise en charge :</strong> <span class=\"kw-alerte\">soins intensifs</span> ou réanimation ; traitement symptomatique ; <strong>pas d'antidote</strong> ; <strong>pas de charbon activé</strong> (<span class=\"kw-ttt\">lithium</span> non carbo-adsorbable) ; <span class=\"kw-ttt\">hémodialyse</span> si intoxication sévère.</li>\n        </ul>\n      </div>\n      <p><strong><span class=\"kw-def\">Suivi</span> du <span class=\"kw-ttt\">lithium</span> :</strong> lithiémie cible <span class=\"kw-chiffre\">0,5-0,8 mmol/L</span> (forme à libération immédiate) ou <span class=\"kw-chiffre\">0,8-1,2 mmol/L</span> (forme à libération prolongée), contrôlée tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> une fois stabilisée ; <span class=\"kw-bio\">bilan rénal</span> et <span class=\"kw-bio\">bilan thyroïdien</span> tous les <span class=\"kw-chiffre\">6 mois</span> ; <span class=\"kw-bio\">calcémie</span> et <span class=\"kw-bio\">ECG</span> <span class=\"kw-chiffre\">1×/an</span>.</p>\n      <p><strong>Antiépileptiques thymorégulateurs</strong> — <span class=\"kw-def\">surveillance</span> et effets indésirables :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Surveillance</span> <span class=\"kw-ttt\">biologique</span> :</strong> <span class=\"kw-bio\">NFS-plaquettes</span> et <span class=\"kw-bio\">bilan hépatique + TP</span> tous <span class=\"kw-clinique\">les</span> mois pendant <span class=\"kw-chiffre\">6 mois</span>, puis tous les <span class=\"kw-chiffre\">6 mois</span> (risque d'<span class=\"kw-alerte\">aplasie médullaire</span> et d'<span class=\"kw-alerte\">hépatotoxicité</span>).</li>\n        <li><strong>Effets indésirables :</strong> neuropsychiques (<span class=\"kw-clinique\">confusion</span>, somnolence, tremblements) ; digestifs avec <span class=\"kw-etio\">hépatite</span> médicamenteuse ; hématologiques (cytopénies) ; dermatologiques — risque de <span class=\"kw-alerte\">syndrome de Stevens-Johnson / Lyell</span> avec la <span class=\"kw-ttt\">lamotrigine</span> ; hyponatrémie par SIADH avec la carbamazépine.</li>\n        <li><strong>Interactions :</strong> la <span class=\"kw-ttt\">carbamazépine</span> est un <strong>inducteur enzymatique</strong> → baisse de l'efficacité des œstroprogestatifs (contraception orale inefficace) ; interactions nombreuses à vérifier systématiquement.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-etio\">Insuffisance rénale chronique</span> · 105 — Epilepsie</em></p>","frequence":3},{"id":"74-24","rang":"A","rubrique":"Définition","titre":"Psychostimulants : connaître les principales classes et molécules","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-ttt\">psychostimulants</span></strong> stimulent la vigilance : ils sont prescrits pour <strong>améliorer l'attention</strong> et réduire la somnolence diurne excessive. Leurs propriétés : stimulation de l'attention, amélioration de la vigilance, effet <strong>anorexigène</strong>, stimulation du système cardiovasculaire.</p>\n      <table >\n        <thead><tr><th></th><th>Méthylphénidate</th><th>Modafinil</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>Inhibiteur de la recapture de la <span class=\"kw-def\">dopamine</span> (et, à moindre degré, de la <span class=\"kw-ttt\">noradrénaline</span>)</td><td>Augmente la transmission <span class=\"kw-def\">dopaminergique</span></td></tr>\n          <tr><td><strong>Formes</strong></td><td>Libération immédiate (durée d'action ~<span class=\"kw-chiffre\">3 h</span>) ; libération prolongée (~<span class=\"kw-chiffre\">6-10 h</span>)</td><td>Prescription sur <strong>ordonnance d'exception</strong></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"74-25","rang":"B","rubrique":"Prise en charge","titre":"Psychostimulants : connaître les indications, les non indications, les contre-indications","contenu":"<p><strong>Indications</strong> des psychostimulants :</p>\n      <table >\n        <thead><tr><th>Molécule</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Méthylphénidate</span></strong></td><td><span class=\"kw-etio\">TDAH</span> chez l'enfant de <span class=\"kw-chiffre\">> 6 ans</span> (si aménagement de l'environnement insuffisant — efficacité ~<span class=\"kw-chiffre\">80 %</span>).<br>Traitement de <strong>2ᵉ ligne</strong> de la somnolence dans la narcolepsie et l'hypersomnie idiopathique (en cas d'échec du modafinil).</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Modafinil</span></strong></td><td>Traitement de <strong>1ʳᵉ intention</strong> de la somnolence dans la narcolepsie et l'hypersomnie idiopathique.</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span> :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-ci\">Grossesse</span>, allaitement</strong> : <span class=\"kw-clinique\">les</span> psychostimulants ne sont pas recommandés.</li>\n        <li><strong>Cardiaques :</strong> <span class=\"kw-ci\">valvulopathies</span> ; <span class=\"kw-etio\">insuffisance cardiaque</span> ; troubles du rythme cardiaque non contrôlés ; <span class=\"kw-ci\">HTA modérée à sévère non contrôlée</span>.</li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> :</strong> <span class=\"kw-ci\">hypersensibilité</span> à la molécule.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 110 — Trouble sommeil</em></p>","frequence":1},{"id":"74-26","rang":"B","rubrique":"Prise en charge","titre":"Psychostimulants : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","contenu":"<table >\n        <thead><tr><th>Méthylphénidate</th><th>Modafinil</th></tr></thead>\n        <tbody>\n          <tr><td>\n            Effets indésirables fréquents mais d'intensité légère, justifiant une <strong><span class=\"kw-def\">surveillance</span> mensuelle</strong> du poids, de la taille, de la FC et de la TA :<br>\n            <strong>Appétit :</strong> diminution, surtout au repas du midi (formes LP) → vigilance sur la <span class=\"kw-alerte\">croissance staturo-pondérale</span><br>\n            <strong>Sommeil :</strong> difficultés d'endormissement → administrer le méthylphénidate <strong>à distance du coucher</strong><br>\n            <strong>Digestif :</strong> <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">céphalées</span> (à l'initiation et lors des augmentations de dose)<br>\n            <strong>Cardiovasculaire :</strong> augmentation modérée de la FC et de la TA, <span class=\"kw-clinique\">palpitations</span> rares<br>\n            <strong>Humeur :</strong> rares cas de tristesse de l'humeur\n          </td><td>\n            Généralement <strong>bien toléré</strong> ; effets indésirables proches du méthylphénidate (insomnie, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">céphalées</span>), plus marqués à l'initiation<br>\n            Augmente rarement la FC et la TA → <span class=\"kw-def\">surveillance</span> recommandée<br>\n            Rares <span class=\"kw-alerte\">réactions cutanées graves</span> (<span class=\"kw-clinique\">syndrome de Stevens</span>-Johnson, nécrolyse épidermique <span class=\"kw-etio\">toxique</span>, <span class=\"kw-alerte\">DRESS</span>) → <strong>arrêt immédiat</strong> du traitement\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Interactions médicamenteuses :</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Méthylphénidate</span> + <span class=\"kw-ci\">vasoconstricteurs décongestionnants</span> (phényléphrine, pseudoéphédrine, naphazoline, oxymétazoline, éphédrine) → risque de <span class=\"kw-alerte\">crise hypertensive</span>.</li>\n        <li><span class=\"kw-ttt\">Méthylphénidate</span> + <span class=\"kw-ci\">IMAO non sélectif</span> → délai de <span class=\"kw-chiffre\">≥ 15 jours</span> à respecter entre la prise des deux médicaments.</li>\n        <li><span class=\"kw-ttt\">Modafinil</span> → peut diminuer l'efficacité des <strong>contraceptifs hormonaux</strong>.</li>\n      </ul>","frequence":1}],"astuces":[{"type":"tip","titre":"Mnémo « QORA / QARA » — antipsychotiques 2ᵉ génération","contenu":"<p><strong>QORA</strong> (épisode maniaque) : <strong>Q</strong>uétiapine · <strong>O</strong>lanzapine · <strong>R</strong>ispéridone · <strong>A</strong>ripiprazole. <strong>QARA</strong> (<span class=\"kw-def\">schizophrénie</span>) : <strong>Q</strong>uétiapine · <strong>A</strong>misulpride · <strong>R</strong>ispéridone · <strong>A</strong>ripiprazole. <span class=\"kw-ttt\">Quétiapine</span> = seule à avoir aussi l'AMM dans l'<span class=\"kw-def\">EDC</span> <span class=\"kw-def\">bipolaire</span> en <span class=\"kw-def\">monothérapie</span>. <strong><span class=\"kw-ttt\">Clozapine</span></strong> réservée à la <span class=\"kw-def\">schizophrénie résistante</span> (<span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">NFS</span> hebdo <span class=\"kw-chiffre\">18 sem</span>).</p>"},{"type":"warn","titre":"Syndrome malin vs syndrome sérotoninergique — différencier","contenu":"<table class=\"matrix\"><thead><tr><th></th><th><span class=\"kw-alerte\">SMN</span></th><th>Sérotoninergique</th></tr></thead><tbody><tr><td>Cause</td><td><span class=\"kw-ttt\">Antipsychotique</span></td><td><span class=\"kw-ttt\">Antidépresseur</span></td></tr><tr><td>Installation</td><td>Progressive (jours)</td><td>Rapide (heures)</td></tr><tr><td>Neuro</td><td><ul><li><strong><span class=\"kw-clinique\">Rigidité</span> extrapyramidale</strong></li><li>↓ vigilance</li></ul></td><td><ul><li><strong><span class=\"kw-clinique\">Hyperréflexie</span></strong></li><li><span class=\"kw-clinique\">Myoclonies</span></li><li><span class=\"kw-clinique\">Mydriase</span></li><li><span class=\"kw-clinique\">Akathisie</span></li></ul></td></tr><tr><td>Bio</td><td><ul><li>↑ <span class=\"kw-bio\">CPK</span></li><li><span class=\"kw-bio\">Hyperleucocytose</span></li><li>↑ Na / K</li></ul></td><td>Peu spécifique</td></tr><tr><td><span class=\"kw-ttt\">Antidote</span></td><td><ul><li><span class=\"kw-ttt\">Bromocriptine</span></li><li><span class=\"kw-ttt\">Dantrolène</span></li><li><span class=\"kw-ttt\">Amantadine</span></li></ul></td><td><span class=\"kw-ttt\">Cyproheptadine</span></td></tr></tbody></table><p><span class=\"kw-clinique\">Les</span> 2 = <span class=\"kw-alerte\">urgence vitale</span>, arrêt du médicament, réa.</p>"},{"type":"tip","titre":"Surveillance AP2G — calendrier à mémoriser","contenu":"<table class=\"matrix\"><thead><tr><th></th><th>Pré</th><th><span class=\"kw-chiffre\">M1</span></th><th><span class=\"kw-chiffre\">M3</span></th><th>/an</th><th>/<span class=\"kw-chiffre\">5 ans</span></th></tr></thead><tbody><tr><td>Poids/IMC</td><td>✓</td><td>✓</td><td>✓</td><td>(/trim)</td><td></td></tr><tr><td>Périmètre abdo</td><td>✓</td><td>✓</td><td></td><td>✓</td><td></td></tr><tr><td><span class=\"kw-bio\">Glycémie</span></td><td>✓</td><td></td><td>✓</td><td>✓</td><td></td></tr><tr><td>Lipides</td><td>✓</td><td></td><td>✓</td><td></td><td>✓</td></tr><tr><td>TA</td><td>✓</td><td></td><td>✓</td><td>✓</td><td></td></tr><tr><td><span class=\"kw-imagerie\">ECG</span> (<span class=\"kw-def\">QTc</span>)</td><td>✓</td><td>✓</td><td></td><td>✓</td><td></td></tr></tbody></table>"},{"type":"warn","titre":"Lithium — la fenêtre thérapeutique étroite","contenu":"<p>Cible <strong><span class=\"kw-chiffre\">0,5-0,8 mmol/L</span></strong> (LI à <span class=\"kw-chiffre\">12 h</span>) ou <strong>0,8-1,2</strong> (LP à <span class=\"kw-chiffre\">12 h</span>). <span class=\"kw-alerte\">Toxicité &gt; 1,5</span>. ↑ par <strong><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC</span>, <span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-clinique\">déshydratation</span>, régime sans sel</strong>. <span class=\"kw-def\">Bilan préthérapeutique</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">iono</span>, <span class=\"kw-bio\">créat</span>/<span class=\"kw-bio\">clairance</span>, <span class=\"kw-bio\">protéinurie</span>, bilan phosphocalcique, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-bio\">β-hCG</span>. <span class=\"kw-bio\">Lithémie</span> à <strong>J5</strong> puis /mois × 3 puis /<span class=\"kw-chiffre\">6 mois</span>. Pas d'<span class=\"kw-ttt\">antidote</span>, pas de <span class=\"kw-ttt\">charbon</span> ; <strong>hémodialyse</strong> en <span class=\"kw-alerte\">surdosage</span> <span class=\"kw-alerte\">sévère</span>.</p>"},{"type":"warn","titre":"Valproate et femme en âge de procréer","contenu":"<p><span class=\"kw-alerte\"><span class=\"kw-ci\">CI absolue</span> chez la femme en âge de procréer sans contraception efficace</span> : <span class=\"kw-alerte\">tératogène</span> (anomalies du tube neural ~<span class=\"kw-chiffre\">10 %</span>, dysmorphie faciale) et <strong>troubles du neurodéveloppement</strong> (autisme, ↓ QI ~<span class=\"kw-chiffre\">30 %</span>). <span class=\"kw-ci\">Programme de prévention</span> obl<span class=\"kw-chiffre\">iga</span>toire (formulaire d'accord de soins, contraception, <span class=\"kw-bio\">β-hCG</span> annuelle). Idem valpromide.</p>"},{"type":"tip","titre":"Durées max réglementaires des BZD","contenu":"<p><strong><span class=\"kw-ttt\">Anxiolytique</span> : <span class=\"kw-chiffre\">12 semaines</span></strong> max, décroissance comprise. <strong><span class=\"kw-ttt\">Hypnotique</span> : <span class=\"kw-chiffre\">4 semaines</span></strong> max. <strong><span class=\"kw-ttt\">Zolpidem</span></strong> : <span class=\"kw-def\">ordonnance sécurisée</span> obl<span class=\"kw-chiffre\">iga</span>toire (en toutes lettres, pas de chevauchement). Chez <strong>≥ <span class=\"kw-chiffre\">65 ans</span></strong> : posologie /2 et <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">4 sem</span> dans tous <span class=\"kw-clinique\">les</span> cas.</p>"},{"type":"info","titre":"Délais d'action à connaître","contenu":"<ul><li><strong><span class=\"kw-ttt\">AD</span></strong> : <span class=\"kw-chiffre\">2-4 sem</span> (<span class=\"kw-def\">EDC</span>), <span class=\"kw-chiffre\">4-8 sem</span> (<span class=\"kw-clinique\">anxiété</span>), <span class=\"kw-chiffre\">8-12 sem</span> (<span class=\"kw-def\">TOC</span>). Réponse trop rapide = suspicion de <span class=\"kw-alerte\">virage maniaque</span>.</li><li><strong><span class=\"kw-ttt\">AP</span></strong> : action sédative rapide (h-j), efficacité <span class=\"kw-ttt\">antipsychotique</span> <span class=\"kw-chiffre\">2-6 sem</span>.</li><li><strong><span class=\"kw-ttt\">Lithium</span></strong> : <span class=\"kw-chiffre\">6-8 sem</span> pour effet prophylactique complet.</li><li><strong><span class=\"kw-ttt\">BZD</span></strong> : effet immédiat (intérêt en crise).</li><li><strong><span class=\"kw-ttt\">Méthylphénidate</span></strong> : effet pharmacologique en <span class=\"kw-chiffre\">30-60 min</span>, durée <span class=\"kw-chiffre\">4-12 h</span> selon forme.</li></ul>"},{"type":"warn","titre":"Associations strictement interdites","contenu":"<ul><li><span class=\"kw-alerte\"><span class=\"kw-ttt\">IMAO</span> + autre <span class=\"kw-ttt\">AD</span></span> (toutes classes) = <span class=\"kw-alerte\">syndrome sérotoninergique</span> potentiellement <span class=\"kw-alerte\">létal</span> — fenêtre de <span class=\"kw-alerte\">sevrage</span> de 14 j.</li><li><span class=\"kw-alerte\">2 BZD</span> (<span class=\"kw-ttt\">anxiolytique</span> + <span class=\"kw-ttt\">hypnotique</span>, ou <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> an</span>xiolytiques).</li><li><span class=\"kw-alerte\">2 médicaments allongeant le QT</span> (<span class=\"kw-ttt\">AP</span> + <span class=\"kw-ttt\">AP</span>, <span class=\"kw-ttt\">AP</span> + macrolide, <span class=\"kw-ttt\">AP</span> + <span class=\"kw-ttt\">méthadone</span>).</li><li><span class=\"kw-alerte\"><span class=\"kw-ttt\">Lithium</span> + <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">diurétiques</span> / <span class=\"kw-ttt\">IEC</span> / <span class=\"kw-ttt\">ARA2</span></span> sans <span class=\"kw-def\">surveillance</span> rapprochée.</li><li><span class=\"kw-alerte\">AD seul chez un bipolaire</span> (<span class=\"kw-alerte\">virage maniaque</span>, accélération des cycles).</li></ul>"}],"strategie":{"urgence":"<p><strong>Syndrome malin des neuroleptiques :</strong> <span class=\"kw-alerte\">urgence vitale</span> — <span class=\"kw-ttt\">arrêt immédiat de l'antipsychotique</span> (molécule <span class=\"kw-ci\">contre-indiquée à vie</span>) + <span class=\"kw-ttt\">transfert en réanimation</span>.<br><strong>Syndrome sérotoninergique :</strong> <span class=\"kw-alerte\">urgence vitale</span> — <span class=\"kw-ttt\">arrêt de l'agent sérotoninergique</span> + <span class=\"kw-ttt\">réanimation</span>, <span class=\"kw-clinique\">évolution</span> rapide possible vers le décès.<br><strong>Intoxication aiguë aux BZD :</strong> risque d'<span class=\"kw-alerte\">asphyxie par obstruction des VAS</span> (<span class=\"kw-alerte\">coma</span> + myorelaxation) ; antidote <span class=\"kw-ttt\">flumazénil</span> si intoxication isolée.<br><strong>Arrêt d'un psychotrope :</strong> jamais d'<span class=\"kw-alerte\">arrêt brutal</span> d'une BZD (risque de <span class=\"kw-alerte\">crise convulsive</span>) ni d'un antipsychotique.</p>","hospit":"<p><strong>Toxidromes graves :</strong> syndrome malin, syndrome sérotoninergique et intoxication aiguë BZD avec <span class=\"kw-alerte\">coma</span> profond relèvent du <span class=\"kw-ttt\">transfert en réanimation</span>.<br><strong>Agitation psychomotrice :</strong> <span class=\"kw-ttt\">antipsychotique sédatif</span> (cyamémazine, loxapine) réservé aux <span class=\"kw-alerte\">états d'agitation sévères</span> ; voie <span class=\"kw-ttt\">per os</span> privilégiée, <span class=\"kw-ttt\">IM</span> si per os impossible.<br><strong><span class=\"kw-ttt\">Sevrage</span> BZD ambulatoire</strong> (le plus fréquent) : médecine générale ou consultation d'addictologie (CSAPA).<br><strong><span class=\"kw-ttt\">Sevrage</span> BZD hospitalier</strong> si : <span class=\"kw-chiffre\">doses très élevées</span>, insomnie rebelle, dépendance à l'<span class=\"kw-etio\">alcool</span>/autre substance, troubles psychiatriques sévères, ATCD de <span class=\"kw-alerte\">syndrome de sevrage sévère et convulsions</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Hyperthermie 40-41°</span> (ou <span class=\"kw-clinique\">hypothermie &lt; 36°</span>) + <span class=\"kw-clinique\">rigidité extrapyramidale</span> sous antipsychotique → <span class=\"kw-etio\">syndrome malin des neuroleptiques</span></li><li><span class=\"kw-clinique\">Myoclonies</span> / <span class=\"kw-clinique\">clonus</span> + <span class=\"kw-clinique\">hyperréflexie</span> + <span class=\"kw-clinique\">mydriase bilatérale</span> + <span class=\"kw-clinique\">hyperthermie</span> sous antidépresseur → <span class=\"kw-etio\">syndrome sérotoninergique</span></li><li><span class=\"kw-clinique\">Coma calme</span> + <span class=\"kw-clinique\">myorelaxation</span> + <span class=\"kw-clinique\">ROT abolis</span> + <span class=\"kw-clinique\">bradypnée</span> → <span class=\"kw-etio\">intoxication aiguë aux BZD</span></li><li><span class=\"kw-clinique\">Convulsions</span>, <span class=\"kw-clinique\">coma</span> ou hallucinations lors d'un <span class=\"kw-etio\">sevrage en BZD</span></li><li><span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">transaminases</span> élevées (<span class=\"kw-etio\">rhabdomyolyse</span>), <span class=\"kw-etio\">CIVD</span>, <span class=\"kw-etio\">choc</span></li><li><span class=\"kw-clinique\">Allongement du QT</span> (<span class=\"kw-chiffre\">&gt; 450 ms</span> homme, <span class=\"kw-chiffre\">&gt; 470 ms</span> femme) → risque de <span class=\"kw-alerte\">torsade de pointes</span> et <span class=\"kw-alerte\">mort subite</span> sous antipsychotique</li><li><span class=\"kw-alerte\">Aggravation des idées suicidaires</span> à l'initiation d'un antidépresseur, surtout chez le sujet jeune (<span class=\"kw-chiffre\">&lt; 24 ans</span>)</li><li><span class=\"kw-alerte\">Virage maniaque de l'humeur</span> sous antidépresseur (réponse trop rapide évoquant un trouble bipolaire)</li></ul>","principes":"<p>La PEC dépend de la situation d'<span class=\"kw-alerte\">urgence</span> rencontrée et impose toujours l'<span class=\"kw-ttt\">arrêt de la molécule en cause</span> + un traitement <span class=\"kw-ttt\">symptomatique</span> avant le traitement spécifique.</p><p><strong>Prescription en situation d'<span class=\"kw-alerte\">urgence</span> (agitation)</strong></p><p>BZD en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ttt\">diazépam</span>, <span class=\"kw-ttt\">clorazépate</span>, <span class=\"kw-ttt\">clonazépam</span> disponibles en IM/IV ; IV lente uniquement avec plateau technique de <span class=\"kw-alerte\">réanimation</span>.</p><ul><li>Voie <span class=\"kw-ttt\">per os</span> privilégiée ; <span class=\"kw-ttt\">IM</span> seulement si per os impossible</li><li><span class=\"kw-ttt\">Antipsychotiques sédatifs</span> IM réservés aux <span class=\"kw-alerte\">agitations sévères</span></li><li><span class=\"kw-ttt\">Monothérapie</span> privilégiée, pas d'<span class=\"kw-ci\">escalade des doses</span> (effet cumulatif différé)</li><li><span class=\"kw-bio\">ECG</span> préalable indispensable (recherche d'un <span class=\"kw-clinique\">QTc long</span>)</li></ul><p><strong>Syndrome malin des neuroleptiques</strong></p><ul><li><span class=\"kw-ttt\">Arrêt de l'antipsychotique</span> en cause (<span class=\"kw-ci\">contre-indiqué à vie</span>)</li><li><span class=\"kw-ttt\">Transfert en réanimation</span> en <span class=\"kw-alerte\">urgence</span></li><li>Symptomatique : <span class=\"kw-ttt\">rééquilibration hydro-électrolytique</span>, <span class=\"kw-ttt\">lutte contre l'hyperthermie</span></li><li>Spécifique : <span class=\"kw-ttt\">bromocriptine</span> (agoniste dopaminergique), <span class=\"kw-ttt\">amantadine</span>, <span class=\"kw-ttt\">dantrolène</span></li></ul><p><strong>Syndrome sérotoninergique</strong></p><p>Prévention : <span class=\"kw-ttt\">monothérapie</span> antidépressive ; <span class=\"kw-ci\">ne jamais</span> associer un <span class=\"kw-ci\">IMAO</span> à un autre antidépresseur.</p><ul><li><span class=\"kw-ttt\">Arrêt immédiat de l'agent sérotoninergique</span></li><li><span class=\"kw-ttt\">Transfert en réanimation</span> + bilan étiologique (<span class=\"kw-etio\">infectieux</span>, métabolique, intoxication)</li><li>Symptomatique : <span class=\"kw-ttt\">rééquilibration hydro-électrolytique</span>, <span class=\"kw-ttt\">lutte contre l'hyperthermie</span></li><li>Spécifique : <span class=\"kw-ttt\">cyproheptadine</span> (antagoniste de la sérotonine), ou <span class=\"kw-ttt\">propranolol</span></li></ul><p><strong>Intoxication aiguë aux BZD</strong></p><p>Flumazénil en intoxication mixte avec tricycliques = risque de <span class=\"kw-alerte\">convulsions fatales</span>.</p><ul><li>Protection des <span class=\"kw-ttt\">voies aériennes</span> + <span class=\"kw-def\">surveillance</span> réanimatoire (demi-vies prolongées)</li><li>Antidote <span class=\"kw-ttt\">flumazénil</span> : bolus IV <span class=\"kw-chiffre\">0,2 mg</span> puis <span class=\"kw-chiffre\">0,1 mg</span> /<span class=\"kw-chiffre\"> 2 min</span>, jusqu'à <span class=\"kw-chiffre\">2 mg</span> max</li><li>Objectif = réveil suffisant pour protéger <span class=\"kw-clinique\">les</span> VAS (éviter l'<span class=\"kw-ttt\">intubation</span>), pas le réveil complet</li><li><span class=\"kw-ci\">Contre-indiqué</span> si épilepsie, suspicion de molécules pro-convulsivantes (<span class=\"kw-ci\">antidépresseurs tricycliques</span>), poly-intoxication sévère</li></ul><p><strong><span class=\"kw-ttt\">Sevrage</span> en BZD</strong></p><ul><li>Arrêt <span class=\"kw-ttt\">extrêmement progressif</span> (plusieurs semaines à plusieurs mois)</li><li>Pas de schéma de décroissance consensuel ; titration en récupérant <span class=\"kw-clinique\">les</span> comprimés non utilisés</li><li>Repérer symptômes de <span class=\"kw-ttt\">sevrage</span> et consommations associées (<span class=\"kw-etio\">alcool</span>, tabac, autres substances)</li><li>Toute diminution de posologie est déjà un résultat favorable (<span class=\"kw-ttt\">réduction</span> des risques)</li></ul>","suivi":"<p><strong>Antipsychotiques :</strong> <span class=\"kw-clinique\">poids/IMC/PA</span>, <span class=\"kw-bio\">glycémie à jeun</span> à <span class=\"kw-chiffre\">M3</span> puis <span class=\"kw-chiffre\">1x/an</span>, <span class=\"kw-bio\">bilan lipidique</span> à <span class=\"kw-chiffre\">M3</span> puis <span class=\"kw-chiffre\">tous les 5 ans</span>, <span class=\"kw-bio\">ECG</span> à <span class=\"kw-chiffre\">M1</span> puis <span class=\"kw-chiffre\">1x/an</span> (<span class=\"kw-ttt\">clozapine</span> : <span class=\"kw-bio\">NFS</span> hebdomadaire <span class=\"kw-chiffre\">18 semaines</span> puis mensuelle).<br><strong>Lithium :</strong> <span class=\"kw-bio\">lithiémie</span>, <span class=\"kw-bio\">bilan rénal</span> et <span class=\"kw-bio\">thyroïdien</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> ; <span class=\"kw-bio\">calcémie</span> + <span class=\"kw-bio\">ECG</span> <span class=\"kw-chiffre\">1x/an</span>.<br><strong>Valproate / carbamazépine / <span class=\"kw-ttt\">lamotrigine</span> :</strong> <span class=\"kw-bio\">NFS-plaquettes</span> et <span class=\"kw-bio\">bilan hépatique</span> mensuels <span class=\"kw-chiffre\">6 mois</span> puis tous les <span class=\"kw-chiffre\">6 mois</span>.<br><strong>Antidépresseurs / anxiolytiques :</strong> pas de bilan <span class=\"kw-ttt\">biologique</span> systématique, mais <span class=\"kw-alerte\">surveillance du risque suicidaire</span> à l'initiation (délai d'action <span class=\"kw-chiffre\">2-4 semaines</span>).</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient sous psychotrope — tableau aigu grave — Trouble de la vigilance, hyperthermie, rigidité ou coma","detail":"<h4>CAT — <span class=\"kw-alerte\">Urgence</span> <span class=\"kw-etio\">toxique</span> chez un patient sous psychotrope — Orientation entre <span class=\"kw-clinique\">les</span> principaux toxidromes et urgences sous psychotropes</h4>","branches":[{"to":"q-myorelax","label":"Tableau aigu","color":"blue"}]},{"id":"q-myorelax","kind":"decision","label":"Coma calme + hypotonie + ROT abolis ? — Pupilles normales, absence de signes végétatifs marqués","branches":[{"to":"t-bzd","label":"Oui — myorelaxation, coma calme","color":"red"},{"to":"q-hyperthermie","label":"Non","color":"blue"}]},{"id":"t-bzd","kind":"terminal","label":"Intoxication aiguë aux BZD — Toxidrome de myorelaxation","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Coma calme</span>, <span class=\"kw-clinique\">myorelaxation</span>, <span class=\"kw-clinique\">ROT abolis</span></li><li><span class=\"kw-clinique\">Bradypnée</span> / <span class=\"kw-alerte\">dépression respiratoire</span> possible, pupilles normales</li></ul><h4>Conduite</h4><ul><li>Protection des <span class=\"kw-ttt\">voies aériennes</span>, risque d'<span class=\"kw-alerte\">asphyxie par obstruction des VAS</span></li><li><span class=\"kw-def\">Surveillance</span> réanimatoire (demi-vies d'élimination prolongées)</li></ul><h4>Traitement</h4><ul><li>Antidote <span class=\"kw-ttt\">flumazénil</span> : bolus IV <span class=\"kw-chiffre\">0,2 mg</span> puis <span class=\"kw-chiffre\">0,1 mg</span>/<span class=\"kw-chiffre\">2 min</span>, max <span class=\"kw-chiffre\">2 mg</span></li><li><span class=\"kw-ci\">CI</span> : épilepsie, suspicion de tricycliques (risque de <span class=\"kw-alerte\">convulsions fatales</span>), poly-intoxication sévère</li></ul>"},{"id":"q-hyperthermie","kind":"decision","label":"Hyperthermie + dysautonomie ? — Sueurs profuses, tachycardie, troubles tensionnels","branches":[{"to":"q-classe","label":"Oui","color":"amber"},{"to":"q-sevrage","label":"Non","color":"blue"}]},{"id":"q-classe","kind":"decision","label":"Médicament en cause ? — Antipsychotique vs antidépresseur sérotoninergique","branches":[{"to":"t-malin","label":"Antipsychotique + rigidité extrapyramidale","color":"red"},{"to":"t-seroto","label":"Antidépresseur + myoclonies / clonus / hyperréflexie","color":"red"}]},{"id":"t-malin","kind":"terminal","label":"Syndrome malin des neuroleptiques — Urgence diagnostique et thérapeutique","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Hyperthermie 40-41°</span> ou <span class=\"kw-clinique\">hypothermie &lt; 36°</span>, <span class=\"kw-clinique\">sueurs</span> profuses</li><li><span class=\"kw-clinique\">Rigidité extrapyramidale</span>, troubles de la vigilance, ± <span class=\"kw-alerte\">convulsions</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperleucocytose &gt; 15 000/mm³</span> à PNN</li><li>Élévation des <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">LDH</span>, <span class=\"kw-bio\">ALAT/ASAT</span> ; troubles du <span class=\"kw-bio\">ionogramme</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Arrêt de l'antipsychotique</span> (<span class=\"kw-ci\">contre-indiqué à vie</span>) + <span class=\"kw-ttt\">réanimation</span></li><li><span class=\"kw-ttt\">Rééquilibration hydro-électrolytique</span>, <span class=\"kw-ttt\">lutte contre l'hyperthermie</span></li><li>Spécifique : <span class=\"kw-ttt\">bromocriptine</span>, <span class=\"kw-ttt\">amantadine</span>, <span class=\"kw-ttt\">dantrolène</span></li></ul>"},{"id":"t-seroto","kind":"terminal","label":"Syndrome sérotoninergique — Évolution rapide possible vers un état critique","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Myoclonies</span>, <span class=\"kw-clinique\">clonus</span>, <span class=\"kw-clinique\">hyperréflexie</span>, <span class=\"kw-clinique\">mydriase bilatérale</span></li><li>Confusion, agitation, <span class=\"kw-clinique\">hyperthermie</span>, <span class=\"kw-clinique\">diarrhée</span>, tremblements</li></ul><h4>Paraclinique</h4><ul><li>Risques : <span class=\"kw-etio\">choc</span>, <span class=\"kw-etio\">coma</span>, <span class=\"kw-etio\">rhabdomyolyse</span>, <span class=\"kw-etio\">CIVD</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Arrêt de l'agent sérotoninergique</span> + <span class=\"kw-ttt\">réanimation</span></li><li><span class=\"kw-ttt\">Rééquilibration hydro-électrolytique</span>, <span class=\"kw-ttt\">lutte contre l'hyperthermie</span></li><li>Spécifique : <span class=\"kw-ttt\">cyproheptadine</span> (antagoniste de la sérotonine)</li></ul>"},{"id":"q-sevrage","kind":"decision","label":"Arrêt ou baisse récente de BZD ? — Tremblements, anxiété, insomnie, ± convulsions","branches":[{"to":"t-sevrage","label":"Oui","color":"amber"}]},{"id":"t-sevrage","kind":"terminal","label":"Syndrome de sevrage aux BZD — Réintroduction puis décroissance progressive","color":"amber","detail":"<h4>Clinique</h4><ul><li>Fréquents : <span class=\"kw-clinique\">tremblements</span>, anxiété, insomnie, <span class=\"kw-clinique\">céphalées</span></li><li>Plus rares : confusion, hallucinations, <span class=\"kw-alerte\">convulsions</span>, <span class=\"kw-alerte\">coma</span></li></ul><h4>Délai</h4><ul><li>Pendant la <span class=\"kw-ttt\">réduction</span>, jusqu'à <span class=\"kw-chiffre\">quelques jours</span> après la dernière prise</li></ul><h4>Conduite</h4><ul><li>Jamais d'<span class=\"kw-alerte\">arrêt brutal</span> : décroissance <span class=\"kw-ttt\">extrêmement progressive</span></li><li><span class=\"kw-alerte\">Hospitalisation</span> si doses très élevées, dépendance à l'<span class=\"kw-etio\">alcool</span>, ATCD de <span class=\"kw-ttt\">sevrage</span> sévère/<span class=\"kw-alerte\">convulsions</span></li></ul>"}]},"cards":[{"i":"04d4fbc3eb65","n":74,"o":"74-1","u":"Définition","t":"Connaître la définition et les principales classes de psychotropes","q":"Quelles sont les six principales classes de psychotropes utilisées en psychiatrie ?","a":"<ul><li><strong>Antipsychotiques</strong></li><li><strong>Antidépresseurs</strong></li><li><strong>Thymorégulateurs</strong></li><li><strong>Anxiolytiques</strong></li><li><strong>Hypnotiques</strong></li><li><strong>Psychostimulants</strong></li></ul>"},{"i":"1d71c000e2b0","n":74,"o":"74-1","u":"Définition","t":"Connaître la définition et les principales classes de psychotropes","q":"Quels neurotransmetteurs sont principalement ciblés par les psychotropes et à quelles fonctions sont-ils associés ?","a":"<ul><li>La <strong>dopamine</strong> est associée au plaisir, à l'émotion et à la motricité.</li><li>La <strong>noradrénaline</strong> est associée à la vigilance, à l'attention et à l'humeur.</li><li>La <strong>sérotonine</strong> est associée à l'humeur, la prise alimentaire et l'émotion.</li><li>Le <strong>GABA</strong> (inhibiteur) est associé à l'émotion et à l'activité neuronale.</li><li>Le <strong>glutamate</strong> (excitateur) est associé à la motricité, la mémoire et l'activité neuronale.</li></ul>"},{"i":"72602dfd5c80","n":74,"o":"74-1","u":"Définition","t":"Connaître la définition et les principales classes de psychotropes","q":"Selon la définition de Delay et Deniker, qu'est-ce qu'un psychotrope ?","a":"<p>Un psychotrope est une substance chimique (naturelle ou artificielle) capable de modifier l'activité mentale. Son tropisme est dit « psychologique ».</p>"},{"i":"08a1047a0006","n":74,"o":"74-11","u":"Prise en charge","t":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","q":"Quels effets indésirables graves spécifiques doit-on rechercher pour les ISRS et IRSNA, les antidépresseurs tricycliques, et pour la venlafaxine en particulier ?","a":"<p>Les effets indésirables graves spécifiques sont :</p><ul><li>Pour les <strong>ISRS et IRSNA</strong> : <strong>Hyponatrémie par SIADH</strong>, syndrome extrapyramidal, <strong>allongement du QT</strong>, interactions via le cytochrome P450, <strong>thrombopathie</strong>.</li><li>Pour les <strong>antidépresseurs tricycliques</strong> : <strong>Allongement du QT</strong>, effets anticholinergiques, effet adrénergique, effet stabilisant de membrane, syndrome pyramidal.</li><li>Pour la <strong>venlafaxine</strong> : Possibilité de pousser d'<strong>HTA</strong>.</li></ul>"},{"i":"1c2e56ba16b3","n":74,"o":"74-11","u":"Prise en charge","t":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","q":"Quels sont les principaux effets indésirables non psychiatriques des antidépresseurs ?","a":"<p>Les principaux effets indésirables non psychiatriques des antidépresseurs sont :</p><ul><li>Effets indésirables <strong>sexuels</strong> (libido, érection), parfois tardifs et durables.</li><li><strong>Prise de poids</strong>.</li><li>Effets bénins fréquents tels que troubles <strong>digestifs</strong> et <strong>tremblements</strong> (précoces, dose-dépendants, transitoires).</li><li>Chez le sujet âgé : troubles de l'<strong>équilibre</strong> et risque d'<strong>hyponatrémie par SIADH</strong>.</li></ul>"},{"i":"984ddf6d2152","n":74,"o":"74-11","u":"Prise en charge","t":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","q":"Quels sont les effets indésirables des antidépresseurs touchant particulièrement la sphère psychique ou comportementale ?","a":"<p>Les effets indésirables des antidépresseurs touchant la sphère psychique ou comportementale sont :</p><ul><li>Un <strong>virage de l'humeur</strong> vers un syndrome maniaque ou des caractéristiques mixtes.</li><li>Une <strong>aggravation des idées suicidaires</strong>, particulièrement à l'initiation du traitement et chez les sujets jeunes, due à une dissociation entre l'effet rapide sur l'inhibition psychomotrice et l'effet retardé sur la tristesse de l'humeur.</li><li>Une majoration transitoire de l'<strong>anxiété</strong> les premiers jours de traitement.</li></ul>"},{"i":"f60cd576f996","n":74,"o":"74-11","u":"Prise en charge","t":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","q":"Quels sont les toxiques fréquemment incriminés dans la survenue d'un syndrome sérotoninergique et quelle est sa prise en charge en urgence ?","a":"<p>Les toxiques fréquemment incriminés sont : <br>Des <strong>antidépresseurs sérotoninergiques</strong> (ISRS, IRSNA), le <strong>tramadol</strong>, les amphétamines (MDMA), la cocaïne, le <strong>lithium</strong>, les triptans, le <strong>millepertuis</strong>.</p><p>La prise en charge en urgence inclut :</p><ul><li><strong>Arrêt immédiat</strong> du ou des médicaments impliqués.</li><li><strong>Transfert en réanimation</strong>.</li><li>Traitement <strong>non spécifique</strong>.</li><li>Administration d'un <strong>antagoniste sérotoninergique</strong>, la <strong>cyproheptadine</strong>.</li></ul>"},{"i":"f6252955f429","n":74,"o":"74-11","u":"Prise en charge","t":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","q":"Qu'est-ce que le syndrome sérotoninergique et quels sont ses signes cliniques principaux ?","a":"<p>Le syndrome sérotoninergique est un effet indésirable rare mais grave, lié à un <strong>excès de sérotonine</strong>, pouvant être mortel. Les signes cliniques principaux sont :</p><ul><li><strong>Signes neurologiques</strong> : confusion, hallucinations, akathisie, tremblements, <strong>myoclonies +++</strong>, rigidité, syndrome pyramidal, hyperréflexie, <strong>mydriase bilatérale</strong>.</li><li><strong>Signes neuro-végétatifs</strong> : tachycardie, HTA ou hypotension, <strong>hyperthermie (40-43 °C)</strong>, sudation, nausées, diarrhée, tachypnée.</li></ul>"},{"i":"f81fac46f4cb","n":74,"o":"74-11","u":"Prise en charge","t":"Antidépresseurs : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses","q":"Comment différencier le syndrome sérotoninergique du syndrome malin des neuroleptiques ?","a":"<p>La différenciation entre le syndrome sérotoninergique et le syndrome malin des neuroleptiques repose sur :</p><ul><li><strong>La cause</strong> : Le syndrome sérotoninergique est lié aux <strong>antidépresseurs sérotoninergiques</strong> ou autres molécules augmentant la sérotonine, tandis que le syndrome malin des neuroleptiques est induit par les <strong>antipsychotiques</strong>.</li><li><strong>La clinique</strong> : Le syndrome sérotoninergique présente des <strong>myoclonies</strong>, une <strong>hyperréflexie</strong>, une <strong>mydriase</strong> et des signes digestifs prédominants avec une hyperthermie, alors que le syndrome malin des neuroleptiques est caractérisé par une <strong>rigidité extrapyramidale</strong> marquée, des sueurs et des troubles de la vigilance, sans myoclonies ni mydriase spécifiques.</li><li><strong>Le traitement spécifique</strong> : La <strong>cyproheptadine</strong> pour le syndrome sérotoninergique, et la <strong>bromocriptine</strong> (amantadine, dantrolène) pour le syndrome malin des neuroleptiques.</li></ul>"},{"i":"1e818f971384","n":74,"o":"74-12","u":"Définition","t":"Anxiolytiques : connaître les principales classes et molécules","q":"Quels sont les anxiolytiques non benzodiazépines mentionnés, leur principal avantage et leurs contre-indications principales respectives ?","a":"<ul><li><strong>Hydroxyzine (Atarax®)</strong> : C'est un <strong>antihistaminique (antagoniste H1)</strong>. Son principal avantage est l'absence de risque de dépendance. Ses contre-indications incluent le <strong>glaucome à angle fermé</strong>, l'<strong>adénome prostatique</strong>, l'<strong>allongement du QT</strong> et le <strong>début de grossesse</strong>.</li><li><strong>Propranolol (Avlocardyl®)</strong> : C'est un <strong>β-bloquant</strong>. Il agit sur les manifestations physiques de l'anxiété. Ses contre-indications majeures sont l'<strong>asthme</strong>, la <strong>BPCO</strong>, l'<strong>insuffisance cardiaque non contrôlée</strong> et les <strong>BAV 2-3 non appareillés</strong>.</li><li><strong>Buspirone (Buspar®)</strong> : C'est un <strong>agoniste 5HT1A</strong>. Son action est retardée (après <strong>1 semaine</strong>). Il ne présente pas de risque de dépendance. Sa contre-indication principale est l'association à un <strong>IMAO</strong> (inhibiteur de la monoamine oxydase).</li></ul>"},{"i":"85333c858d52","n":74,"o":"74-12","u":"Définition","t":"Anxiolytiques : connaître les principales classes et molécules","q":"Quel est le mécanisme d'action principal des benzodiazépines (BZD) en tant qu'anxiolytiques ?","a":"<p>Les benzodiazépines (BZD) agissent en <strong>facilitant la transmission GABAergique</strong>, notamment en activant les <strong>récepteurs GABA-A</strong>. Cela contribue à diminuer l'hyperexcitabilité neuronale associée à l'anxiété.</p>"},{"i":"92353dd353c7","n":74,"o":"74-12","u":"Définition","t":"Anxiolytiques : connaître les principales classes et molécules","q":"Quelles sont les benzodiazépines (BZD) anxiolytiques à demi-vie courte et celles à demi-vie longue, et laquelle est à privilégier chez certaines populations spécifiques ?","a":"<ul><li><strong>Demi-vie courte :</strong> <strong>Oxazépam</strong> et <strong>Lorazépam</strong>. L'Oxazépam est à privilégier chez l'<strong>insuffisant hépatique</strong>, la <strong>personne âgée</strong> et la <strong>femme enceinte</strong>.</li><li><strong>Demi-vie longue :</strong> <strong>Alprazolam</strong> et <strong>Diazépam</strong>.</li></ul>"},{"i":"ef358295599e","n":74,"o":"74-12","u":"Définition","t":"Anxiolytiques : connaître les principales classes et molécules","q":"Quelles autres classes médicamenteuses peuvent avoir un effet anxiolytique selon le contexte clinique ?","a":"<ul><li>Les <strong>antidépresseurs</strong> peuvent être utilisés comme traitement de fond des troubles anxieux.</li><li>Les <strong>antipsychotiques sédatifs</strong> comme le <strong>cyamémazine</strong> ou la <strong>lévomépromazine</strong> peuvent être utilisés pour un traitement symptomatique de courte durée de l'anxiété de l'adulte en cas d'échec des traitements habituels.</li></ul>"},{"i":"44a883074ac6","n":74,"o":"74-14","u":"Prise en charge","t":"Anxiolytiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelle est la voie d'administration des anxiolytiques benzodiazépines (BZD) à privilégier et pourquoi l'interrogatoire et la clinique sont-ils importants avant leur prescription ?","a":"<p>La <strong>voie orale</strong> est à privilégier pour les anxiolytiques BZD. Il n'y a pas de bilan paraclinique systématique avant leur initiation. L'interrogatoire et l'examen clinique sont cruciaux pour <strong>éliminer les contre-indications</strong> potentielles et anticiper les <strong>interactions médicamenteuses</strong>.</p>"},{"i":"62f8d0006af5","n":74,"o":"74-14","u":"Prise en charge","t":"Anxiolytiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les précautions spécifiques concernant la prescription des anxiolytiques benzodiazépines chez les patients âgés de 65 ans et plus ?","a":"<p>Chez les patients de 65 ans et plus :</p><ul><li>Le traitement par BZD n'est <strong>non reconductible au-delà de 4 semaines</strong> sans réévaluation médicale. La date d'arrêt doit être stipulée au patient et consignée dans le dossier.</li><li>Les <strong>posologies d'initiation</strong> doivent être <strong>divisées par 2</strong> par rapport à celles de l'adulte jeune.</li></ul>"},{"i":"d4031ef3a378","n":74,"o":"74-14","u":"Prise en charge","t":"Anxiolytiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les règles de posologie et d'association des benzodiazépines anxiolytiques ?","a":"<p>Les règles sont les suivantes :</p><ul><li>Utiliser la <strong>dose minimale efficace</strong>.</li><li>Respecter les <strong>posologies recommandées</strong>.</li><li>Ne <strong>jamais associer deux benzodiazépines</strong>, même pour des indications différentes.</li></ul>"},{"i":"def40adc24c7","n":74,"o":"74-14","u":"Prise en charge","t":"Anxiolytiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Comment doit être géré l'arrêt d'un traitement par benzodiazépines anxiolytiques et quel est le risque d'un arrêt brutal ?","a":"<p>L'arrêt d'un traitement par benzodiazépines doit <strong>toujours être progressif</strong>, sur une durée adaptée à celle du traitement. Un arrêt brutal expose à un risque de <strong>crise convulsive</strong>.</p>"},{"i":"f4a75f6c37b2","n":74,"o":"74-14","u":"Prise en charge","t":"Anxiolytiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les durées maximales réglementaires de prescription des anxiolytiques et des hypnotiques benzodiazépines, sevrage inclus ?","a":"<p>Les durées maximales réglementaires, sevrage inclus, sont :</p><ul><li>Pour les <strong>anxiolytiques</strong> : <strong>12 semaines</strong>.</li><li>Pour les <strong>hypnotiques</strong> : <strong>4 semaines</strong>.</li></ul>"},{"i":"61c3edd718ad","n":74,"o":"74-15","u":"Prise en charge","t":"Anxiolytiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les conséquences des anxiolytiques sur la cognition et l'effet de rebond à l'arrêt du traitement ?","a":"<ul><li><strong>Cognition</strong> : altération de la <strong>mémoire</strong>, réalisation d'<strong>actes automatiques amnésiques</strong> (amnésie antérograde avec conséquences médico-légales possibles). Une <strong>confusion</strong> est possible, surtout chez le sujet âgé.</li><li><strong>Effet rebond</strong> : réapparition temporaire de symptômes anxieux ou d'insomnie avec une <strong>intensité supérieure</strong> à celle d'avant le traitement, après son arrêt.</li></ul>"},{"i":"871437ba8060","n":74,"o":"74-15","u":"Prise en charge","t":"Anxiolytiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quels sont les effets indésirables des anxiolytiques liés à la sédation et sur le comportement ?","a":"<ul><li><strong>Sédation</strong> : somnolence diurne, asthénie, sensations vertigineuses, altération de la vigilance (imposant des précautions pour la conduite automobile). Ces effets sont potentialisés par l'<strong>alcool</strong> et les autres sédatifs.</li><li><strong>Comportement</strong> : effet <strong>désinhibiteur</strong> et réactions paradoxales (agitation, agressivité), particulièrement favorisées par l'<strong>alcool</strong> et fréquentes chez les <strong>adolescents</strong>.</li></ul>"},{"i":"eaf926f949ba","n":74,"o":"74-15","u":"Prise en charge","t":"Anxiolytiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Comment les anxiolytiques interagissent-ils avec d'autres médicaments et substances ?","a":"<p>Bien qu'aucune association ne soit formellement contre-indiquée, l'association d'anxiolytiques avec d'autres <strong>médicaments sédatifs</strong> ou l'<strong>alcool</strong> potentialise la <strong>dépression du système nerveux central</strong>, augmentant ainsi les effets sédatifs et le risque de confusion.</p>"},{"i":"ec7129b32d24","n":74,"o":"74-15","u":"Prise en charge","t":"Anxiolytiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quel est l'effet indésirable principal des anxiolytiques, notamment les benzodiazépines ?","a":"<p>L'effet indésirable principal des anxiolytiques, particulièrement les benzodiazépines, est la <strong>dépendance</strong>. Elle se caractérise par une <strong>perte d'efficacité</strong> du traitement (tolérance pharmacologique) et un <strong>syndrome de sevrage</strong> en cas d'arrêt brutal.</p>"},{"i":"ed86f7afd88a","n":74,"o":"74-15","u":"Prise en charge","t":"Anxiolytiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les particularités des effets indésirables des anxiolytiques chez le sujet âgé ?","a":"<p>Chez le <strong>sujet âgé</strong>, les anxiolytiques augmentent le risque de <strong>confusion</strong>, de <strong>chutes</strong> et de <strong>fractures</strong>. Ces risques sont liés à la sédation et aux effets cérébelleux.</p>"},{"i":"3c2a1d935591","n":74,"o":"74-16","u":"Prise en charge","t":"Anxiolytiques : connaître les modalités de prescription en situation d’urgence","q":"Dans quelles situations d'urgence les benzodiazépines sont-elles indiquées ?","a":"<p>Les benzodiazépines sont indiquées dans les situations d'urgence suivantes :</p><ul><li>Un <strong>état d'agitation</strong>.</li><li>Des <strong>crises convulsives</strong> ou un <strong>état de mal épileptique</strong>.</li><li>La <strong>prévention ou le traitement du syndrome de sevrage alcoolique</strong>, notamment le delirium tremens.</li></ul>"},{"i":"b3461076c1b5","n":74,"o":"74-16","u":"Prise en charge","t":"Anxiolytiques : connaître les modalités de prescription en situation d’urgence","q":"Quelle est la voie d'administration des benzodiazépines à privilégier en urgence et quelles sont les molécules disponibles par cette voie ?","a":"<p>En urgence, la voie orale est à privilégier pour les benzodiazépines. Les molécules disponibles par cette voie sont le <strong>diazépam</strong>, le <strong>clorazépate dipotassique</strong> et le <strong>clonazépam</strong>.</p>"},{"i":"e0dc1e085611","n":74,"o":"74-16","u":"Prise en charge","t":"Anxiolytiques : connaître les modalités de prescription en situation d’urgence","q":"Quelles sont les modalités d'administration parentérale des benzodiazépines en urgence et leurs inconvénients ou risques spécifiques ?","a":"<p>Les modalités d'administration parentérale sont :</p><ul><li>La <strong>voie intramusculaire (IM)</strong> : elle est utilisée si la voie orale est impossible. Son inconvénient est une <strong>résorption incomplète</strong>, une <strong>distribution lente et irrégulière</strong>.</li><li>La <strong>voie intraveineuse (IV) lente</strong> : rarement utilisée mais possible pour certaines molécules (notamment dans l'état de mal épileptique). Elle <strong>augmente le risque de dépression respiratoire</strong> et doit être réalisée avec un <strong>plateau technique de réanimation à proximité</strong>.</li></ul>"},{"i":"1a134f9f6cd7","n":74,"o":"74-17","u":"Définition","t":"Hypnotiques : connaître les principales classes et molécules","q":"Quelle est la définition des hypnotiques en pharmacologie ?","a":"<p>Les hypnotiques sont des psychotropes qui ont pour principale action d'<strong>induire le sommeil</strong>. Ils sont proches des anxiolytiques et favorisent l'endormissement en réduisant l'anxiété du soir grâce à leurs propriétés anxiolytiques et sédatives.</p>"},{"i":"d1421245eb9c","n":74,"o":"74-17","u":"Définition","t":"Hypnotiques : connaître les principales classes et molécules","q":"Quelles sont les principales classes pharmacologiques d'hypnotiques et les molécules associées ?","a":"<ul><li>Les <strong>benzodiazépines (BZD) hypnotiques</strong> : <stron>lormétazépam</stron>, <strong>loprazolam</strong>, <strong>nitrazépam</strong>, <strong>estazolam</strong>.</li><li>Les <strong>apparentés aux BZD</strong>, appelés « médicaments en Z » : <strong>zolpidem</strong>, <strong>zopiclone</strong>.</li><li>Les <strong>antihistaminiques</strong> capables de traverser la barrière hémato-encéphalique : <strong>doxylamine</strong>, <strong>alimémazine</strong>.</li></ul>"},{"i":"f66a60349a92","n":74,"o":"74-17","u":"Définition","t":"Hypnotiques : connaître les principales classes et molécules","q":"La mélatonine est-elle considérée comme un hypnotique au sens pharmacologique classique ?","a":"<p>Non, la <strong>mélatonine ne doit pas être considérée comme un hypnotique</strong> au sens pharmacologique classique en raison de son mécanisme d'action différent et de son indication comme régulateur du cycle veille-sommeil plutôt que comme inducteur direct du sommeil.</p>"},{"i":"1177e7fcfe3f","n":74,"o":"74-18","u":"Prise en charge","t":"Hypnotiques : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients âgés","q":"Quelle est la seule indication des hypnotiques, notamment les benzodiazépines et apparentés (zolpidem, zopiclone) ?","a":"<p>La seule indication des hypnotiques est l'<strong>insomnie aiguë transitoire</strong>.</p><p>Il n'existe <strong>aucune indication</strong> pour l'insomnie chronique.</p>"},{"i":"7216f9c3efd0","n":74,"o":"74-18","u":"Prise en charge","t":"Hypnotiques : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les contre-indications absolues à la prescription d'hypnotiques (benzodiazépines et apparentés) ?","a":"<ul><li><strong>Hypersensibilité connue</strong> à la substance active</li><li><strong>Insuffisance respiratoire sévère</strong></li><li><strong>Myasthénie</strong></li><li><strong>Grossesse</strong> et <strong>allaitement</strong> (pour la plupart)</li><li>Chez l'<strong>enfant</strong> (spécifiquement le zolpidem et le zopiclone)</li></ul>"},{"i":"f4e37718ac61","n":74,"o":"74-18","u":"Prise en charge","t":"Hypnotiques : connaître les indications, les non indications, les contre-indications à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les contre-indications relatives à la prescription d'hypnotiques (benzodiazépines et apparentés) ?","a":"<ul><li><strong>Insuffisance hépatique</strong> (sauf l'oxazépam qui peut être utilisé avec précaution)</li><li><strong>Syndrome d'apnées obstructives du sommeil (SAOS) non traité par pression positive continue (PPC)</strong></li><li><strong>Insuffisance rénale</strong></li><li>Antécédents de <strong>troubles affectifs</strong></li><li>Antécédents de <strong>réaction paradoxale</strong> aux benzodiazépines ou apparentés</li></ul>"},{"i":"0e17d7bfc99d","n":74,"o":"74-19","u":"Prise en charge","t":"Hypnotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Comment doit être effectué l'arrêt d'un traitement par hypnotiques ?","a":"<p>L'arrêt d'un traitement par hypnotiques doit toujours être <strong>progressif</strong>, sur une durée adaptée à la situation clinique du patient.</p>"},{"i":"7db8b1b9b0e2","n":74,"o":"74-19","u":"Prise en charge","t":"Hypnotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelle est la durée maximale de prescription des hypnotiques chez l'adulte pour le traitement d'une insomnie ?","a":"<p>La durée maximale des hypnotiques est de <strong>4 semaines</strong>, en incluant la période de sevrage.</p>"},{"i":"9327620d2bc0","n":74,"o":"74-19","u":"Prise en charge","t":"Hypnotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Est-il recommandé d'associer deux hypnotiques pour le traitement d'une insomnie ?","a":"<p>Non, il ne faut <strong>jamais associer 2 hypnotiques</strong> pour le traitement d'une insomnie.</p>"},{"i":"d658aed40527","n":74,"o":"74-19","u":"Prise en charge","t":"Hypnotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les particularités de la prescription du ZOLPIDEM en France ?","a":"<p>Le Zolpidem doit être prescrit sur une <strong>ordonnance sécurisée</strong>. Il est impératif d'écrire en toutes lettres :</p><ul><li>Le <strong>nombre d'unités par prise</strong></li><li>Le <strong>nombre de prises</strong></li><li>Le <strong>dosage</strong></li></ul><p>L'<strong>absence de chevauchement</strong> est la règle, sauf mention contraire.</p>"},{"i":"f79de1f9f9b2","n":74,"o":"74-19","u":"Prise en charge","t":"Hypnotiques : connaître les règles de bon usage à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles précautions prendre lors de l'instauration d'un traitement hypnotique chez un patient de 65 ans ou plus ?","a":"<p>Chez le patient de 65 ans ou plus, la <strong>posologie d'initiation doit être divisée par 2</strong>. Une <strong>réévaluation rapprochée</strong> est nécessaire.</p>"},{"i":"0133dd37a3b8","n":74,"o":"74-20","u":"Prise en charge","t":"Hypnotiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les principales interactions médicamenteuses à prendre en compte avec les hypnotiques ?","a":"<p>Les hypnotiques interagissent avec tous les autres médicaments <strong>sédatifs</strong>, y compris l'<strong>alcool</strong>. Ces associations entraînent une <strong>potentialisation</strong> des effets sédatifs, augmentant ainsi le risque d'effets indésirables.</p>"},{"i":"76e9065d23f6","n":74,"o":"74-20","u":"Prise en charge","t":"Hypnotiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quel est le risque lié à l'arrêt des hypnotiques et quel est son mécanisme principal ?","a":"<p>L'arrêt des hypnotiques expose à un <strong>syndrome de sevrage</strong>, lié à la <strong>dépendance</strong>. Il peut se manifester notamment par un <strong>rebond de l'insomnie</strong>, avec une perte d'efficacité du traitement.</p>"},{"i":"cf4798720443","n":74,"o":"74-20","u":"Prise en charge","t":"Hypnotiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quelles sont les complications spécifiques des hypnotiques chez le sujet âgé ?","a":"<p>Chez le sujet âgé, les hypnotiques sont associés à un risque accru de :</p><ul><li><strong>Confusion mentale</strong>.</li><li><strong>Chutes</strong> et <strong>fractures</strong>.</li></ul>"},{"i":"eeec3222696e","n":74,"o":"74-20","u":"Prise en charge","t":"Hypnotiques : connaître les effets indésirables fréquents ou graves, principales interactions médicamenteuses à tous les âges de la vie, notamment chez les patients âgés","q":"Quels sont les principaux effets indésirables des hypnotiques sur le système nerveux central ?","a":"<p>Les hypnotiques peuvent entraîner :</p><ul><li>Une <strong>sédation diurne</strong> (somnolence, asthénie, altération de la vigilance).</li><li>Une <strong>altération de la mémoire et de la cognition</strong>, pouvant se manifester par des <strong>actes automatiques amnésiques</strong>.</li><li>Des <strong>réactions paradoxales</strong> (agitation, agressivité, effet désinhibiteur).</li></ul>"},{"i":"0297291dbb9c","n":74,"o":"74-21","u":"Définition","t":"Thymorégulateurs : connaître les principales classes et molécules","q":"Quelle est la double approche pharmacologique dans la prise en charge du trouble bipolaire ?","a":"<p>L'approche pharmacologique du trouble bipolaire est double :</p><ul><li>Traiter les <strong>accès aigus</strong> (ex: antipsychotiques pour l'accès maniaque, antidépresseurs avec prudence pour l'épisode dépressif).</li><li>Modifier le cours évolutif de la maladie en <strong>prévenant la récidive des accès</strong> (traitement de fond).</li></ul>"},{"i":"7d2c41116d48","n":74,"o":"74-21","u":"Définition","t":"Thymorégulateurs : connaître les principales classes et molécules","q":"Quelles sont les principales classes de molécules utilisées comme thymorégulateurs, et quels exemples de molécules appartiennent à ces classes ?","a":"<ul><li>Le <strong>lithium</strong> (ex: Carbonate de lithium, Téralithe®), qui est le traitement de référence des troubles bipolaires.</li><li>Les <strong>antiépileptiques</strong> (ex: acide valproïque, valpromide, carbamazépine, lamotrigine).</li><li>Les <strong>antipsychotiques de 2<sup>ème</sup> génération</strong> (ex: olanzapine), qui ont une action thymorégulatrice par régulation de la dopamine.</li></ul>"},{"i":"b3638d77de1d","n":74,"o":"74-21","u":"Définition","t":"Thymorégulateurs : connaître les principales classes et molécules","q":"Qu'est-ce qu'un thymorégulateur et quel est son objectif principal dans le traitement des troubles de l'humeur ?","a":"<p>Un thymorégulateur, également appelé normothymique ou thymoisoleptique, est un <strong>stabilisateur de l'humeur</strong>. Son objectif principal est de <strong>diminuer la fréquence, la durée et l'intensité des épisodes thymiques</strong>, qu'ils soient maniaques ou dépressifs.</p>"},{"i":"394400e74bed","n":74,"o":"74-24","u":"Définition","t":"Psychostimulants : connaître les principales classes et molécules","q":"Quelles sont les principales molécules de psychostimulants et leurs mécanismes d'action ?","a":"<p>Les principales molécules psychostimulantes mentionnées sont :</p><ul><li>Le <strong>méthylphénidate</strong> : C'est un inhibiteur de la recapture de la <strong>dopamine</strong> et, à un moindre degré, de la <strong>noradrénaline</strong>.</li><li>Le <strong>modafinil</strong> : Il augmente la transmission <strong>dopaminergique</strong>.</li></ul>"},{"i":"e18c6ae17003","n":74,"o":"74-24","u":"Définition","t":"Psychostimulants : connaître les principales classes et molécules","q":"Quelle est la définition des psychostimulants et leurs propriétés principales ?","a":"<p>Les psychostimulants sont des substances qui <strong>stimulent la vigilance</strong>. Ils sont principalement prescrits pour <strong>améliorer l'attention</strong> et <strong>réduire la somnolence diurne excessive</strong>.<br>Leurs propriétés incluent :</p><ul><li>Stimulation de l'attention</li><li>Amélioration de la vigilance</li><li>Effet <strong>anorexigène</strong></li><li>Stimulation du système cardiovasculaire</li></ul>"},{"i":"fe0c532bcf49","n":74,"o":"74-24","u":"Définition","t":"Psychostimulants : connaître les principales classes et molécules","q":"Sous quelles formes le méthylphénidate est-il disponible et comment est-il prescrit ?","a":"<p>Le méthylphénidate est disponible sous deux formes :</p><ul><li><strong>Libération immédiate</strong>, avec une durée d'action d'environ <strong>3 heures</strong>.</li><li><strong>Libération prolongée</strong>, avec une durée d'action d'environ <strong>6 à 10 heures</strong>.</li></ul><p>Sa prescription se fait sur <strong>ordonnance d'exception</strong>.</p>"},{"i":"05f7051f23b7","n":74,"o":"74-3","u":"Définition","t":"Antipsychotiques : connaître les principales classes et molécules","q":"Citez des exemples de molécules d'antipsychotiques atypiques (2ème génération).","a":"<ul><li><strong>Amisulpride</strong>.</li><li><strong>Aripiprazole</strong>.</li><li>Ceux en \"-apine\" : <strong>loxapine</strong>, <strong>olanzapine</strong>, <strong>clozapine</strong>, <strong>quétiapine</strong>.</li><li>Ceux en \"-péridone\" : <strong>rispéridone</strong>, <strong>palipéridone</strong>.</li></ul>"},{"i":"38fb82e1cfef","n":74,"o":"74-3","u":"Définition","t":"Antipsychotiques : connaître les principales classes et molécules","q":"Quelle est la caractéristique pharmacologique commune à tous les antipsychotiques ?","a":"<p>Sur le plan pharmacologique, tous les antipsychotiques sont des antagonistes des récepteurs dopaminergiques de type <strong>D2</strong>.</p>"},{"i":"61b1ac0433b3","n":74,"o":"74-3","u":"Définition","t":"Antipsychotiques : connaître les principales classes et molécules","q":"Comment les antipsychotiques sont-ils classés et quels sont les noms des classes ?","a":"<p>Les antipsychotiques sont classés en deux générations :</p><ul><li>Les antipsychotiques <strong>typiques</strong> (ou 1ère génération).</li><li>Les antipsychotiques <strong>atypiques</strong> (ou 2ème génération).</li></ul>"},{"i":"d3b953c5589d","n":74,"o":"74-3","u":"Définition","t":"Antipsychotiques : connaître les principales classes et molécules","q":"Quel est un piège classique concernant les antipsychotiques et d'autres médicaments ?","a":"<p>Un piège classique est que certains antiémétiques comme le <strong>métoclopramide</strong> sont des antipsychotiques \"cachés\", car ils possèdent également des propriétés antagonistes des récepteurs dopaminergiques <strong>D2</strong>.</p>"},{"i":"e531b22d83c6","n":74,"o":"74-3","u":"Définition","t":"Antipsychotiques : connaître les principales classes et molécules","q":"Citez des exemples de molécules d'antipsychotiques typiques (1ère génération), en précisant leur classe pharmacologique si pertinent.","a":"<ul><li>Phénothiazines : <strong>cyamémazine</strong>, <strong>alimémazine</strong>, <strong>lévomépromazine</strong>, <strong>chlorpromazine</strong>.</li><li>Benzamide : <strong>sulpiride</strong>.</li><li>Thioxanthène : <strong>flupenthixol</strong>.</li><li>Butyrophénone : <strong>halopéridol</strong>.</li></ul>"},{"i":"3c7cb807e280","n":74,"o":"74-7","u":"Identifier une urgence","t":"Antipsychotiques : connaître les modalités de prescription en situation d’urgence","q":"Quel examen complémentaire est indispensable avant la prescription d'antipsychotiques en urgence ?","a":"<p>Un <strong>électrocardiogramme (ECG)</strong> préalable reste <strong>indispensable</strong> avant la prescription d'antipsychotiques en urgence, même si sa réalisation peut être difficile dans ces situations.</p>"},{"i":"97a1708b4156","n":74,"o":"74-7","u":"Identifier une urgence","t":"Antipsychotiques : connaître les modalités de prescription en situation d’urgence","q":"Quelles sont les précautions à prendre concernant la posologie des antipsychotiques et la monothérapie en urgence psychiatrique ?","a":"<p>Il est important d'<strong>éviter l'escalade des doses</strong> afin de prévenir un risque d'effet cumulatif différé sur la vigilance. Il faut également <strong>privilégier la monothérapie</strong>.</p>"},{"i":"b02f2fd3a1df","n":74,"o":"74-7","u":"Identifier une urgence","t":"Antipsychotiques : connaître les modalités de prescription en situation d’urgence","q":"Quelle est la voie d'administration à privilégier pour les antipsychotiques en situation d'urgence psychiatrique ?","a":"<p>En situation d'urgence (état d'agitation, contexte psychotique aigu), la voie <strong>per os</strong> (orale) est à privilégier pour l'administration des antipsychotiques.</p>"},{"i":"e7b9a47a2729","n":74,"o":"74-7","u":"Identifier une urgence","t":"Antipsychotiques : connaître les modalités de prescription en situation d’urgence","q":"Quand la voie intramusculaire doit-elle être envisagée pour l'administration d'antipsychotiques en urgence ?","a":"<p>La voie <strong>intramusculaire (IM)</strong> doit être utilisée uniquement en cas d'<strong>impossibilité de la voie orale</strong>. Le recours à des antipsychotiques à visée sédative par voie IM doit être réservé aux <strong>états d'agitation sévères</strong>.</p>"},{"i":"35e44ab4c20e","n":74,"o":"74-8","u":"Définition","t":"Antidépresseurs : connaître les principales classes et molécules","q":"Quel est le mécanisme d'action spécifique des antidépresseurs 'autres' comme la mirtazapine, la miansérine et l'agomélatine ?","a":"<ul><li>La <strong>mirtazapine</strong> et la <strong>miansérine</strong> sont des <strong>antagonistes des récepteurs alpha2-adrénergiques</strong>.</li><li>L'<strong>agomélatine</strong> est un <strong>agoniste des récepteurs de la mélatonine</strong> et un <strong>antagoniste des récepteurs 5-HT2C</strong>.</li></ul>"},{"i":"4c592068e22a","n":74,"o":"74-8","u":"Définition","t":"Antidépresseurs : connaître les principales classes et molécules","q":"Quel est le mécanisme d'action général des antidépresseurs ?","a":"<p>Les antidépresseurs agissent en restaurant des concentrations en <strong>sérotonine</strong> et en <strong>noradrénaline</strong> proches de la normale, et stimulent la <strong>neurogenèse</strong>. Cela peut se faire par 3 voies principales :</p><ul><li>Inhibition de la recapture présynaptique des neurotransmetteurs.</li><li>Blocage des récepteurs présynaptiques alpha-adrénergiques.</li><li>Inhibition de la dégradation par la monoamine oxydase A.</li></ul>"},{"i":"dddf5198f321","n":74,"o":"74-8","u":"Définition","t":"Antidépresseurs : connaître les principales classes et molécules","q":"Quelles sont les principales classes d'antidépresseurs et citer des molécules associées à chacune ?","a":"<ul><li><strong>ISRS</strong> (Inhibiteurs Sélectifs de la Recapture de la Sérotonine) : <strong>Escitalopram</strong>, <strong>citalopram</strong>, <strong>sertraline</strong>, paroxétine, fluvoxamine, fluoxétine.</li><li><strong>IRSNA</strong> (Inhibiteurs de la Recapture de la Sérotonine et de la Noradrénaline) : <strong>Venlafaxine</strong>, milnacipran.</li><li><strong>Imipraminiques</strong> (antidépresseurs tricycliques) : <strong>Amitriptyline</strong>, clomipramine.</li><li><strong>IMAO</strong> (Inhibiteurs de la Monoamine Oxydase A) : <strong>Moclobémide</strong>.</li><li><strong>Autres antidépresseurs</strong> : <strong>Mirtazapine</strong>, <strong>miansérine</strong>, agomélatine.</li></ul>"},{"i":"1cf6409d0110","n":74,"o":"74-9","u":"Prise en charge","t":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","q":"Quelles sont les contre-indications absolues des antidépresseurs imipraminiques ?","a":"<p>Les contre-indications absolues des antidépresseurs imipraminiques sont :</p><ul><li>L'<strong>association aux IMAO</strong>.</li><li>L'<strong>hypersensibilité</strong>.</li><li>Le <strong>glaucome à angle fermé</strong> et l'<strong>adénome de prostate</strong> en raison de leurs effets anticholinergiques.</li><li>Les contre-indications cardiovasculaires : <strong>infarctus du myocarde récent</strong>, <strong>syndrome coronaire aigu non stabilisé</strong>, <strong>trouble du rythme cardiaque non contrôlé</strong>, <strong>insuffisance cardiaque décompensée</strong>.</li></ul>"},{"i":"20c43369db57","n":74,"o":"74-9","u":"Prise en charge","t":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","q":"Quelles sont les contre-indications absolues des IMAO ?","a":"<p>Les contre-indications absolues des IMAO sont :</p><ul><li>L'<strong>association aux autres antidépresseurs</strong> (sauf rares exceptions et sous surveillance stricte).</li><li>L'<strong>hypersensibilité</strong>.</li><li>L'<strong>hypertension artérielle non contrôlée</strong>.</li><li>Le <strong>phéochromocytome</strong>.</li><li>L'<strong>accident vasculaire cérébral récent</strong>.</li><li>Les <strong>polynévrites</strong>.</li><li>L'<strong>alimentation riche en tryptophane et tyramine</strong> (fromage fermenté, sauce soja, hareng en saumure, bière, vin) en raison du risque de crise hypertensive.</li></ul>"},{"i":"361f2e3f850e","n":74,"o":"74-9","u":"Prise en charge","t":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","q":"Outre les troubles de l'humeur et anxieux, quelles sont les autres indications des antidépresseurs ?","a":"<p>Les antidépresseurs peuvent être indiqués dans :</p><ul><li>Les <strong>douleurs neuropathiques</strong> (notamment les imipraminiques et les IRSNA).</li><li>Les <strong>céphalées rebelles et migraines</strong> (notamment les imipraminiques et les IMAO).</li><li>Certains <strong>troubles du sommeil</strong> comme la narcolepsie avec cataplexie et l'énurésie.</li></ul>"},{"i":"699a532d28b4","n":74,"o":"74-9","u":"Prise en charge","t":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","q":"Dans quels troubles anxieux les antidépresseurs sont-ils indiqués ?","a":"<p>Les antidépresseurs sont indiqués dans :</p><ul><li>Le <strong>trouble anxieux généralisé</strong> (TAG).</li><li>Le <strong>trouble panique</strong>.</li><li>Le <strong>trouble phobique</strong> (phobie sociale, agoraphobie).</li><li>Le <strong>trouble de stress post-traumatique</strong> (TSPT).</li><li>Les <strong>troubles obsessionnels compulsifs</strong> (TOC).</li></ul>"},{"i":"cacd7d9391a2","n":74,"o":"74-9","u":"Prise en charge","t":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","q":"Quelles sont les contre-indications absolues des ISRS/IRSNA ?","a":"<p>Les contre-indications absolues des ISRS/IRSNA sont :</p><ul><li>L'<strong>association aux IMAO</strong> en raison du risque de <strong>syndrome sérotoninergique</strong>.</li><li>L'<strong>hypersensibilité</strong> à la substance active.</li></ul>"},{"i":"dec67f5fa423","n":74,"o":"74-9","u":"Prise en charge","t":"Antidépresseurs : connaître les indications, les non indications, les contre-indications","q":"Quelles sont les principales indications des antidépresseurs dans les troubles de l'humeur ?","a":"<p>Les antidépresseurs sont indiqués dans :</p><ul><li>L'<strong>épisode dépressif caractérisé</strong> (en initiation et en consolidation).</li><li>Le <strong>trouble dépressif récurrent</strong> (en phase de maintenance).</li></ul>"}]};